<?php
defined('BASEPATH') OR exit('No direct script access allowed');

class Instansi extends CI_Controller {
    
    public function __construct() {
        parent::__construct();
        
        date_default_timezone_set("Asia/Jakarta");
        
        // Load database jika belum
        if (!isset($this->db)) {
            $this->load->database();
        }
    }

    /**
     * Cek apakah user sudah login
     */
    private function is_logged_in() {
        if (isset($_SESSION['isLoggedIn']) && $_SESSION['isLoggedIn'] === true) {
            return true;
        }
        if (isset($this->session) && $this->session->userdata('isLoggedIn') === true) {
            return true;
        }
        if (!empty($_SESSION['Username']) || isset($_SESSION['Level']) || !empty($_SESSION['KodeWilayah'])) {
            return true;
        }
        if (isset($this->session) && ($this->session->userdata('Username') || $this->session->userdata('Level') !== null)) {
            return true;
        }
        return false;
    }

    /**
     * Cek apakah user memiliki role 4 (Instansi)
     */
    private function is_role_4() {
        return $this->is_logged_in() && isset($_SESSION['Level']) && (int)$_SESSION['Level'] === 4;
    }

    /**
     * Cek apakah user memiliki role 3 (Akun Daerah / Verifikator)
     */
    private function is_role_3() {
        return $this->is_logged_in() && isset($_SESSION['Level']) && (int)$_SESSION['Level'] === 3;
    }

    /**
     * Cek apakah user saat ini adalah level Nasional (Level 0)
     */
    private function is_nasional() {
        if (isset($_SESSION['Level']) && ((string)$_SESSION['Level'] === '0' || strtolower((string)$_SESSION['Level']) === 'nasional')) {
            return true;
        }
        if (isset($this->session) && $this->session->userdata('Level') !== null) {
            $lvl = $this->session->userdata('Level');
            if ((string)$lvl === '0' || strtolower((string)$lvl) === 'nasional') return true;
        }
        return false;
    }

    /**
     * Cek apakah user saat ini adalah level Kementerian (Level 1)
     */
    private function is_kementerian() {
        if (isset($_SESSION['Level']) && ((string)$_SESSION['Level'] === '1' || strtolower((string)$_SESSION['Level']) === 'kementerian')) {
            return true;
        }
        if (isset($this->session) && $this->session->userdata('Level') !== null) {
            $lvl = $this->session->userdata('Level');
            if ((string)$lvl === '1' || strtolower((string)$lvl) === 'kementerian') return true;
        }
        if (isset($_SESSION['userLevel']) && (string)$_SESSION['userLevel'] === '1') {
            return true;
        }
        if (isset($_SESSION['IdKementerian']) && !empty($_SESSION['IdKementerian']) && empty($_SESSION['Instansi'])) {
            return true;
        }
        return false;
    }

    /**
     * Cek apakah user saat ini berstatus Read-Only untuk dokumen LKPJ Daerah (Kementerian & Nasional)
     */
    private function is_lkpj_readonly() {
        return $this->is_kementerian() || $this->is_nasional();
    }

    /**
     * Cek apakah user memiliki hak akses mengubah / CRUD data LKPJ BAB 1 & 2
     * User Kementerian dan Nasional HANYA BISA MELIHAT DATA (Read-only), TIDAK BISA CRUD
     */
    private function can_crud_lkpj() {
        if ($this->is_lkpj_readonly()) {
            return false;
        }
        return true;
    }

    /**
     * Cek apakah user memiliki hak akses mengubah / CRUD data LKPJ sesuai dengan session wilayahnya masing-masing.
     * Aturan:
     * - User harus login dan tidak read-only (bukan Kementerian / Nasional).
     * - Superadmin (Level === 0) memiliki akses penuh.
     * - User Daerah (Level 3) & Instansi (Level 4) hanya dapat melakukan CRUD jika KodeWilayah akun miliknya sesuai dengan wilayah data yang diakses.
     */
    private function can_crud_lkpj_for_wilayah($targetKodeWilayah = null) {
        if (!$this->is_logged_in()) {
            return false;
        }
        if ($this->is_lkpj_readonly()) {
            return false;
        }
        // Superadmin (Level 0) bisa mengelola semua wilayah
        if (isset($_SESSION['Level']) && (int)$_SESSION['Level'] === 0) {
            return true;
        }
        if (isset($this->session) && (int)$this->session->userdata('Level') === 0) {
            return true;
        }

        // Ambil session kode wilayah asli pengguna
        $sessionKw = null;
        if ($this->is_role_4()) {
            $instansi_id = $this->get_instansi_id();
            if ($instansi_id) {
                $inst = $this->db->select('kodewilayah')->where('id', $instansi_id)->get('akun_instansi')->row_array();
                if (!empty($inst['kodewilayah'])) {
                    $sessionKw = trim((string)$inst['kodewilayah']);
                }
            }
        }
        if (empty($sessionKw)) {
            $sessionKw = $this->session->userdata('KodeWilayah') ?: (isset($_SESSION['KodeWilayah']) ? $_SESSION['KodeWilayah'] : null);
        }
        if (empty($sessionKw) && isset($_SESSION['Username']) && !empty($_SESSION['Username'])) {
            $user = $this->db->select('KodeWilayah')->where('Username', $_SESSION['Username'])->get('akun')->row_array();
            if (!empty($user['KodeWilayah'])) {
                $sessionKw = trim((string)$user['KodeWilayah']);
            }
        }

        if (empty($sessionKw)) {
            return false;
        }

        if (empty($targetKodeWilayah)) {
            return true;
        }

        return trim((string)$sessionKw) === trim((string)$targetKodeWilayah);
    }



    /**
     * Cek apakah user bisa melakukan CRUD (role 4 atau role 3/admin dengan instansi aktif)
     */
    private function can_crud() {
        if ($this->is_role_4()) {
            return true;
        }
        if ($this->is_role_3() || (isset($_SESSION['Level']) && (int)$_SESSION['Level'] === 0)) {
            $instansi_id = $this->get_instansi_id();
            return !empty($instansi_id);
        }
        return false;
    }

    /**
     * Mendapatkan ID instansi dari session atau parameter filter
     */
    private function get_instansi_id() {
        if ($this->is_role_4()) {
            return isset($_SESSION['IdInstansi']) ? (int)$_SESSION['IdInstansi'] : null;
        }
        if (isset($_SESSION['TempInstansiId']) && !empty($_SESSION['TempInstansiId'])) {
            return (int)$_SESSION['TempInstansiId'];
        }
        $filter_instansi = $this->input->get('instansi_id', TRUE) ?: $this->input->post('instansi_id', TRUE);
        if (!empty($filter_instansi) && is_numeric($filter_instansi)) {
            return (int)$filter_instansi;
        }
        if (isset($_SESSION['FilterInstansiId']) && !empty($_SESSION['FilterInstansiId'])) {
            return (int)$_SESSION['FilterInstansiId'];
        }
        return null;
    }

    /**
     * Mendapatkan kode wilayah dari session
     */
    private function get_kode_wilayah() {
        // 1. Jika user login sebagai Role 4 (Instansi), kodewilayah HARUS diambil dari akun_instansi miliknya (tidak bisa dibypass)
        if ($this->is_role_4()) {
            $instansi_id = $this->get_instansi_id();
            if ($instansi_id) {
                $inst = $this->db->select('kodewilayah')->where('id', $instansi_id)->get('akun_instansi')->row_array();
                if (!empty($inst['kodewilayah'])) {
                    $this->session->set_userdata('KodeWilayah', $inst['kodewilayah']);
                    $_SESSION['KodeWilayah'] = $inst['kodewilayah'];
                    return $inst['kodewilayah'];
                }
            }
        }

        // 2. Jika user login sebagai Role 3 (Daerah), kodewilayah HARUS dikunci ke wilayah akun daerahnya
        if ($this->is_role_3()) {
            $kw = $this->session->userdata('KodeWilayah') ?: (isset($_SESSION['KodeWilayah']) ? $_SESSION['KodeWilayah'] : null);
            if (!empty($kw)) {
                return $kw;
            }
            if (isset($_SESSION['Username']) && !empty($_SESSION['Username'])) {
                $user = $this->db->select('KodeWilayah')->where('Username', $_SESSION['Username'])->get('akun')->row_array();
                if (!empty($user['KodeWilayah'])) {
                    $this->session->set_userdata('KodeWilayah', $user['KodeWilayah']);
                    $_SESSION['KodeWilayah'] = $user['KodeWilayah'];
                    return $user['KodeWilayah'];
                }
            }
        }

        // 3. Cek query parameter get 'kode_wilayah' atau 'KodeWilayah' jika belum login atau jika role read-only (Kementerian / Nasional)
        $getKw = $this->input->get('kode_wilayah', TRUE) ?: $this->input->get('KodeWilayah', TRUE);
        if ((!$this->is_logged_in() || $this->is_lkpj_readonly()) && !empty($getKw)) {
            $this->session->set_userdata('TempKodeWilayah', $getKw);
            $_SESSION['TempKodeWilayah'] = $getKw;
            return $getKw;
        }

        // 4. Cek TempKodeWilayah (misal untuk Admin yang memilih wilayah, atau user belum login yang memilih dropdown)
        $tempKw = $this->session->userdata('TempKodeWilayah') ?: (isset($_SESSION['TempKodeWilayah']) ? $_SESSION['TempKodeWilayah'] : null);
        if (!empty($tempKw)) {
            return $tempKw;
        }

        // 5. Cek session KodeWilayah
        $kw = $this->session->userdata('KodeWilayah') ?: (isset($_SESSION['KodeWilayah']) ? $_SESSION['KodeWilayah'] : null);
        if (!empty($kw)) {
            return $kw;
        }

        // 6. Jika session kosong, ambil langsung dari tabel akun berdasarkan user login
        if (isset($_SESSION['Username']) && !empty($_SESSION['Username'])) {
            $user = $this->db->select('KodeWilayah')->where('Username', $_SESSION['Username'])->get('akun')->row_array();
            if (!empty($user['KodeWilayah'])) {
                $this->session->set_userdata('KodeWilayah', $user['KodeWilayah']);
                $_SESSION['KodeWilayah'] = $user['KodeWilayah'];
                return $user['KodeWilayah'];
            }
        }

        // 7. Default fallback Situbondo
        return '35.12';
    }

    /**
     * Set TempKodeWilayah (untuk filter wilayah)
     */
    // Di controller Instansi.php
public function SetTempKodeWilayah() {
    if (!$this->input->is_ajax_request()) {
        show_404();
        return;
    }
    
    $kodeWilayah = $this->input->post('KodeWilayah', TRUE);
    $instansiId = $this->input->post('InstansiId', TRUE);
    
    if ($kodeWilayah && $this->db->where('Kode', $kodeWilayah)->get('kodewilayah')->num_rows() > 0) {
        $this->session->set_userdata('TempKodeWilayah', $kodeWilayah);
        
        // ✅ SIMPAN JUGA INSTANSI ID
        if (!empty($instansiId) && is_numeric($instansiId)) {
            $this->session->set_userdata('TempInstansiId', $instansiId);
        } else {
            $this->session->unset_userdata('TempInstansiId');
        }
        
        echo '1';
    } else {
        echo 'Kode Wilayah tidak valid';
    }
}

// Tambah method untuk reset filter
public function ResetTempFilter() {
    if (!$this->input->is_ajax_request()) {
        show_404();
        return;
    }
    $this->session->unset_userdata('TempKodeWilayah');
    $this->session->unset_userdata('TempInstansiId');
    echo '1';
}

    /**
     * Halaman Permasalahan PD
     */
    public function PermasalahanPD() {
        $Header['Halaman'] = 'Permasalahan PD';
        
        $KodeWilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        $is_logged_in = $this->is_logged_in();
        $is_role_4 = $this->is_role_4();
        $level = isset($_SESSION['Level']) ? $_SESSION['Level'] : null;
        
        $data['KodeWilayah'] = $KodeWilayah;
        $data['InstansiId'] = $instansi_id;
        $data['IsLoggedIn'] = $is_logged_in;
        $data['IsRole4'] = $is_role_4;
        $data['Level'] = $level;
        $data['NamaInstansi'] = isset($_SESSION['NamaInstansi']) ? $_SESSION['NamaInstansi'] : '';
        
        // Ambil nama wilayah
        $data['NamaWilayah'] = '';
        if ($KodeWilayah) {
            $wilayah = $this->db->select('Nama')->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            $data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
        }
        
        // Filter Instansi yang dipilih (untuk NON role 4)
        $filter_instansi_id = $this->input->get('instansi_id', TRUE);
        $data['FilterInstansiId'] = $filter_instansi_id;
        
        // Data provinsi untuk dropdown filter
        $data['Provinsi'] = $this->db->where("Kode LIKE '__'")
                                     ->order_by('Nama')
                                     ->get('kodewilayah')
                                     ->result_array();
        
        // ========== AMBIL DAFTAR INSTANSI UNTUK FILTER ==========
        $data['ListInstansi'] = [];
        if (!$is_role_4 && $KodeWilayah) {
            $data['ListInstansi'] = $this->db->select('id, nama')
                ->from('akun_instansi')
                ->where('kodewilayah', $KodeWilayah)
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        }
        
        // Ambil data Masalah Pokok (untuk dropdown)
        $data['MasalahPokok'] = [];
        if ($KodeWilayah) {
            $data['MasalahPokok'] = $this->db->select('Id, NamaPermasalahanPokok')
                ->from('permasalahanpokokdaerah')
                ->where('KodeWilayah', $KodeWilayah)
                ->where('deleted_at IS NULL')
                ->order_by('Id', 'ASC')
                ->get()
                ->result_array();
        }
        
        // ========== AMBIL DATA PERMASALAHAN PD ==========
        $data['PermasalahanPD'] = [];
        
        if ($KodeWilayah || $instansi_id) {
            $this->db->select('p.*, mp.NamaPermasalahanPokok, a.nama as nama_instansi')
                ->from('permasalahan_pd p')
                ->join('permasalahanpokokdaerah mp', 'mp.Id = p.masalah_pokok', 'left')
                ->join('akun_instansi a', 'a.id = p.instansi_id', 'left');
            
            // Filter berdasarkan role
            if ($is_role_4 && $instansi_id) {
                $this->db->where('p.instansi_id', $instansi_id);
                $this->db->where('p.kodewilayah', $KodeWilayah);
            } elseif ($KodeWilayah) {
                $this->db->where('p.kodewilayah', $KodeWilayah);
                
                if (!empty($filter_instansi_id) && $filter_instansi_id != '') {
                    $this->db->where('p.instansi_id', (int)$filter_instansi_id);
                }
            }
            
            $this->db->where('p.deleted_at IS NULL')
                     ->order_by('p.id', 'ASC');
            
            $data['PermasalahanPD'] = $this->db->get()->result_array();
        }
        
        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/PermasalahanPD', $data);
    }

    /**
     * Input Permasalahan PD (AJAX) - HANYA UNTUK ROLE 4
     */
    public function InputPermasalahanPD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        
        if (!$this->can_crud()) {
            echo "Akses ditolak! Hanya Instansi yang dapat menambah data.";
            return;
        }
        
        $kode_wilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        
        if (!$kode_wilayah) {
            echo "Wilayah belum dipilih!";
            return;
        }
        
        if (!$instansi_id) {
            echo "Data instansi tidak ditemukan!";
            return;
        }
        
        $masalah = trim($this->input->post('masalah', true));
        if (!$masalah) {
            echo "Masalah harus diisi!";
            return;
        }
        
        $masalah_pokok_id = (int)$this->input->post('masalah_pokok', true);
        
        if ($masalah_pokok_id > 0 && $kode_wilayah) {
            $cek = $this->db->where('Id', $masalah_pokok_id)
                ->where('KodeWilayah', $kode_wilayah)
                ->where('deleted_at IS NULL')
                ->get('permasalahanpokokdaerah')
                ->row_array();
            
            if (!$cek) {
                $masalah_pokok_id = null;
            }
        } else {
            $masalah_pokok_id = null;
        }
        
        $data = [
            'kodewilayah'      => $kode_wilayah,
            'instansi_id'      => $instansi_id,
            'masalah_pokok'    => $masalah_pokok_id,
            'masalah'          => $masalah,
            'penyebab_masalah' => trim($this->input->post('penyebab_masalah', true)),
            'faktor_internal'  => trim($this->input->post('faktor_internal', true)),
            'faktor_external'  => trim($this->input->post('faktor_external', true)),
            'akar_masalah'     => trim($this->input->post('akar_masalah', true)),
            'created_at'       => date('Y-m-d H:i:s')
        ];
        
        $this->db->insert('permasalahan_pd', $data);
        echo $this->db->affected_rows() > 0 ? '1' : 'Gagal menyimpan data!';
    }

    /**
     * Edit Permasalahan PD (AJAX) - HANYA UNTUK ROLE 4
     */
    public function EditPermasalahanPD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        
        if (!$this->can_crud()) {
            echo "Akses ditolak! Hanya Instansi yang dapat mengedit data.";
            return;
        }
        
        $id = (int)$this->input->post('id', true);
        $instansi_id = $this->get_instansi_id();
        
        if (!$id) {
            echo "ID tidak valid!";
            return;
        }
        
        if (!$instansi_id) {
            echo "Data instansi tidak ditemukan!";
            return;
        }
        
        $existing = $this->db->where('id', $id)
            ->where('deleted_at IS NULL')
            ->get('permasalahan_pd')
            ->row_array();
        
        if (!$existing) {
            echo "Data tidak ditemukan!";
            return;
        }
        
        if ($existing['instansi_id'] != $instansi_id) {
            echo "Akses ditolak! Anda hanya dapat mengedit data instansi sendiri.";
            return;
        }
        
        $masalah = trim($this->input->post('masalah', true));
        if (!$masalah) {
            echo "Masalah harus diisi!";
            return;
        }
        
        $masalah_pokok_id = (int)$this->input->post('masalah_pokok', true);
        
        if ($masalah_pokok_id > 0 && $existing['kodewilayah']) {
            $cek = $this->db->where('Id', $masalah_pokok_id)
                ->where('KodeWilayah', $existing['kodewilayah'])
                ->where('deleted_at IS NULL')
                ->get('permasalahanpokokdaerah')
                ->row_array();
            
            if (!$cek) {
                $masalah_pokok_id = null;
            }
        } else {
            $masalah_pokok_id = null;
        }
        
        $data = [
            'masalah_pokok'    => $masalah_pokok_id,
            'masalah'          => $masalah,
            'penyebab_masalah' => trim($this->input->post('penyebab_masalah', true)),
            'faktor_internal'  => trim($this->input->post('faktor_internal', true)),
            'faktor_external'  => trim($this->input->post('faktor_external', true)),
            'akar_masalah'     => trim($this->input->post('akar_masalah', true)),
            'updated_at'       => date('Y-m-d H:i:s')
        ];
        
        $this->db->where('id', $id);
        $this->db->update('permasalahan_pd', $data);
        
        echo $this->db->affected_rows() > 0 ? '1' : 'Tidak ada perubahan data!';
    }

    /**
     * Hapus Permasalahan PD (AJAX) - HANYA UNTUK ROLE 4
     */
    public function HapusPermasalahanPD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        
        if (!$this->can_crud()) {
            echo "Akses ditolak! Hanya Instansi yang dapat menghapus data.";
            return;
        }
        
        $id = (int)$this->input->post('id', true);
        $instansi_id = $this->get_instansi_id();
        
        if (!$id) {
            echo "ID tidak valid!";
            return;
        }
        
        if (!$instansi_id) {
            echo "Data instansi tidak ditemukan!";
            return;
        }
        
        $existing = $this->db->where('id', $id)
            ->where('deleted_at IS NULL')
            ->get('permasalahan_pd')
            ->row_array();
        
        if (!$existing) {
            echo "Data tidak ditemukan!";
            return;
        }
        
        if ($existing['instansi_id'] != $instansi_id) {
            echo "Akses ditolak! Anda hanya dapat menghapus data instansi sendiri.";
            return;
        }
        
        $this->db->where('id', $id);
        $this->db->update('permasalahan_pd', [
            'deleted_at' => date('Y-m-d H:i:s')
        ]);
        
        echo $this->db->affected_rows() > 0 ? '1' : 'Gagal menghapus data!';
    }

    /**
     * Get list Kab/Kota (untuk filter) - DIPERBAIKI
     */
   /**
 * Get list Kab/Kota (untuk filter) - DIPERBAIKI
 */
public function GetListKabKota() {
    $kode_provinsi = $this->input->post('Kode', TRUE) ?: $this->input->get('Kode', TRUE);
    if (empty($kode_provinsi)) {
        $kode_provinsi = $this->input->post('kode', TRUE) ?: $this->input->get('kode', TRUE);
    }
    
    if (empty($kode_provinsi)) {
        $this->output->set_content_type('application/json')->set_output(json_encode([]));
        return;
    }
    
    $prov2 = substr(trim($kode_provinsi), 0, 2);
    $kode_pattern = $prov2 . '.%';
    
    $kabkota = $this->db
        ->select('Kode, Nama')
        ->from('kodewilayah')
        ->where('Kode LIKE', $kode_pattern)
        ->where('LENGTH(REPLACE(Kode, ".", "")) = 4', null, false)
        ->order_by('Nama', 'ASC')
        ->get()
        ->result_array();
    
    $this->output
        ->set_content_type('application/json')
        ->set_output(json_encode($kabkota));
}

    /**
     * Get list Provinsi
     */
    public function GetListProvinsi() {
        $provinsi = $this->db->where("Kode LIKE '__'")
                             ->order_by('Nama')
                             ->get('kodewilayah')
                             ->result_array();
        
        $this->output
            ->set_content_type('application/json')
            ->set_output(json_encode($provinsi));
    }

    /**
     * Get list Instansi Level 4 berdasarkan kode wilayah (AJAX)
     */
    public function GetListInstansiLevel4() {
        $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: $this->input->get('kode_wilayah', TRUE);
        if (!$kode_wilayah) {
            $kode_wilayah = $this->input->post('KodeWilayah', TRUE) ?: $this->input->get('KodeWilayah', TRUE);
        }
        if (!$kode_wilayah) {
            $kode_wilayah = $this->input->post('Kode', TRUE) ?: $this->input->get('Kode', TRUE);
        }
        if (!$kode_wilayah) {
            $this->output->set_content_type('application/json')->set_output(json_encode([]));
            return;
        }
        
        $provKode = substr($kode_wilayah, 0, 2);
        $instansi = $this->db->select('id, nama')
            ->from('akun_instansi')
            ->where("(kodewilayah = " . $this->db->escape($kode_wilayah) . " OR kodewilayah = " . $this->db->escape($provKode) . ")")
            ->where('deleted_at IS NULL')
            ->order_by('nama', 'ASC')
            ->get()
            ->result_array();
        
        $this->output
            ->set_content_type('application/json')
            ->set_output(json_encode($instansi));
    }

