    // Validasi kepemilikan data
    $existing = $this->db->where('id', $id)
        ->where('kode_wilayah', $kode_wilayah)
        ->where('deleted_at IS NULL')
        ->get('rumusanrenstra_header')
        ->row_array();
    
    if (!$existing) {
