    $Header['Halaman'] = 'IKU Perangkat Daerah';
    
    $KodeWilayah = $this->get_kode_wilayah();
    $instansi_id = $this->get_instansi_id();
    $is_logged_in = $this->is_logged_in();
    $is_role_4 = $this->is_role_4();
    $filter_instansi_id = $this->input->get('instansi_id', TRUE);
    
    $data['KodeWilayah'] = $KodeWilayah;
    $data['InstansiId'] = $instansi_id;
    $data['IsLoggedIn'] = $is_logged_in;
    $data['IsRole4'] = $is_role_4;
    $data['FilterInstansiId'] = $filter_instansi_id;
    $data['NamaInstansi'] = isset($_SESSION['NamaInstansi']) ? $_SESSION['NamaInstansi'] : '';
    
    // Ambil nama wilayah
    $data['NamaWilayah'] = '';
    if ($KodeWilayah) {
        $wilayah = $this->db->select('Nama')->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
        $data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
    }
    
    // Data provinsi untuk dropdown filter
    $data['Provinsi'] = $this->db->where("Kode LIKE '__'")
                                 ->order_by('Nama')
                                 ->get('kodewilayah')
                                 ->result_array();
    
    // Daftar instansi untuk filter
    $data['ListInstansi'] = [];
    if (!$is_role_4 && $KodeWilayah) {
        $data['ListInstansi'] = $this->db->select('id, nama')
            ->from('akun_instansi')
            ->where('kodewilayah', $KodeWilayah)
            ->where('deleted_at IS NULL')
            ->order_by('nama', 'ASC')
            ->get()
            ->result_array();
    }
    
    // ========== AMBIL DATA IKU PD ==========
    $data['Data'] = [];
    
    // Auto-migration check untuk kolom rumus dan definisi_operasional
    if (!$this->db->field_exists('rumus', 'iku_pd')) {
        $this->load->dbforge();
        $this->dbforge->add_column('iku_pd', [
            'rumus' => ['type' => 'TEXT', 'null' => TRUE, 'after' => 'indikator']
        ]);
    }
    if (!$this->db->field_exists('definisi_operasional', 'iku_pd')) {
        $this->load->dbforge();
        $this->dbforge->add_column('iku_pd', [
            'definisi_operasional' => ['type' => 'TEXT', 'null' => TRUE, 'after' => 'rumus']
        ]);
    }
    
    if ($KodeWilayah) {
        $query = $this->db->from('iku_pd')
            ->where('kode_wilayah', $KodeWilayah)
            ->where('deleted_at IS NULL');
        
        if ($is_role_4 && $instansi_id) {
            $query->where('id_instansi', $instansi_id);
        } elseif (!empty($filter_instansi_id)) {
            $query->where('id_instansi', (int)$filter_instansi_id);
        }
        
        $data['Data'] = $query->order_by('id', 'ASC')->get()->result_array();
    }
    
    $this->load->view('Daerah/header', $Header);
    $this->load->view('Daerah/IkuPD', $data);
}

/**
 * Input IKU PD (AJAX) - HANYA UNTUK ROLE 4
 */
public function InputIkuPD() {
    if (!$this->input->is_ajax_request()) {
        show_404();
        return;
    }
    
    if (!$this->can_crud()) {
        echo "Akses ditolak! Hanya Instansi yang dapat menambah data.";
        return;
    }
    
    $KodeWilayah = $this->get_kode_wilayah();
    $instansi_id = $this->get_instansi_id();
    
    if (!$KodeWilayah) {
        echo "Wilayah belum dipilih!";
        return;
    }
    
    if (!$instansi_id) {
        echo "Data instansi tidak ditemukan!";
        return;
    }
    
    $indikator = trim($this->input->post('indikator', true));
    $satuan = trim($this->input->post('satuan', true));
    $rawRumus = (string)$this->input->post('rumus', FALSE);
    $rumus = trim(strip_tags($rawRumus, '<sup><sub>'));
    $defInput = $this->input->post('definisi_operasional', true);
    $definisi = !empty($defInput) ? trim($defInput) : null;
    
    if (empty($indikator)) {
        echo "Indikator harus diisi!";
        return;
    }
    
    if (empty($satuan)) {
        echo "Satuan harus diisi!";
        return;
    }
    
    $cleanTarget = function($v) {
        if ($v === null || $v === '') return null;
        $val = str_replace(',', '.', trim((string)$v));
        return is_numeric($val) ? $val : null;
    };

    $data = [
        'kode_wilayah'   => $KodeWilayah,
        'id_instansi'    => $instansi_id,
        'indikator'      => $indikator,
        'rumus'          => !empty($rumus) ? $rumus : null,
        'definisi_operasional' => $definisi,
        'satuan'         => $satuan,
        'baseline_2024'  => $cleanTarget($this->input->post('baseline_2024', true)),
        't_2025'         => $cleanTarget($this->input->post('t_2025', true)),
        't_2026'         => $cleanTarget($this->input->post('t_2026', true)),
        't_2027'         => $cleanTarget($this->input->post('t_2027', true)),
        't_2028'         => $cleanTarget($this->input->post('t_2028', true)),
        't_2029'         => $cleanTarget($this->input->post('t_2029', true)),
        't_2030'         => $cleanTarget($this->input->post('t_2030', true)),
        'keterangan'     => $this->input->post('keterangan', true),
        'created_at'     => date('Y-m-d H:i:s')
    ];
    
    $this->db->insert('iku_pd', $data);
    echo $this->db->affected_rows() > 0 ? '1' : 'Gagal menyimpan!';
}

