        'satuan'         => $satuan,
        'baseline_2024'  => $cleanTarget($this->input->post('baseline_2024', true)),
        't_2025'         => $cleanTarget($this->input->post('t_2025', true)),
        't_2026'         => $cleanTarget($this->input->post('t_2026', true)),
