    // ================================================================
    // DPA (DOKUMEN PELAKSANAAN ANGGARAN)
    // ================================================================

    public function DPA() {
        $Header['Halaman'] = 'DPA';
        
        $KodeWilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        $is_role_4 = $this->is_role_4();
        $tahun = $this->input->get('tahun', TRUE);
        $filter_instansi = $this->input->get('instansi_id', TRUE);
        
        if ($is_role_4 && $instansi_id) {
            $filter_instansi = (int)$instansi_id;
        }
        
        // Data Provinsi untuk filter
        $Data['Provinsi'] = $this->db
            ->where("Kode LIKE '__'")
            ->order_by('Nama')
            ->get('kodewilayah')
            ->result_array();
        
        $is_logged_in = $this->is_logged_in();
        $Data['IsLoggedIn'] = $is_logged_in;
        $Data['KodeWilayah'] = $KodeWilayah;
        $Data['NamaWilayah'] = '';
        $Data['IsRole4'] = $is_role_4;
        $Data['IsDaerah'] = $is_logged_in && !$is_role_4;
        $Data['InstansiId'] = $instansi_id;
        $Data['ControllerName'] = 'Instansi';
        
        // Ambil Nama Wilayah jika ada
        if (!empty($KodeWilayah)) {
            $wilayah = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            $Data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
        }
        
        // List Instansi
        $Data['ListInstansi'] = [];
        if ($is_role_4 && !empty($instansi_id)) {
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where('id', (int)$instansi_id)
                ->where('deleted_at IS NULL')
                ->get()
                ->result_array();
        } elseif (!empty($KodeWilayah)) {
            $provKode = substr($KodeWilayah, 0, 2);
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where("(kodewilayah = " . $this->db->escape($KodeWilayah) . " OR kodewilayah = " . $this->db->escape($provKode) . ")")
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        } else {
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        }
        
        // List Tahun
        $dbYears = $this->db->select('DISTINCT(tahun) as thn')
            ->where('deleted_at IS NULL')
            ->order_by('tahun', 'DESC')
            ->get('belanja_sub_kegiatan_header')
            ->result_array();
        
        $listTahun = [];
        if (!empty($dbYears)) {
            foreach ($dbYears as $dy) {
                if (!empty($dy['thn'])) {
                    $listTahun[] = (int)$dy['thn'];
                }
            }
        }
        $currentY = (int)date('Y');
        for ($y = $currentY + 1; $y >= $currentY - 5; $y--) {
            if (!in_array($y, $listTahun)) {
                $listTahun[] = $y;
            }
        }
        rsort($listTahun);
        $Data['ListTahun'] = $listTahun;
        
        if (empty($tahun)) {
            if (!empty($dbYears) && !empty($dbYears[0]['thn'])) {
                $tahun = $dbYears[0]['thn'];
            } else {
                $tahun = date('Y');
            }
        }
        $Data['TahunAktif'] = $tahun;
        $Data['FilterInstansi'] = $filter_instansi;

        // Ambil Data Hierarki DPA
        if (!$is_logged_in && empty($KodeWilayah)) {
            $Data['DPAData'] = [];
        } else {
            $Data['DPAData'] = $this->_buildDPAHierarchy($KodeWilayah, $tahun, $filter_instansi);
        }
        
        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/DPA', $Data);
    }

    public function GetDPAData() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $KodeWilayah = $this->get_kode_wilayah();
        $is_role_4 = $this->is_role_4();
        $instansi_id = $this->get_instansi_id();
        $tahun = $this->input->post('tahun', TRUE) ?: date('Y');
        $filter_instansi = $this->input->post('instansi', TRUE);

        if ($is_role_4 && $instansi_id) {
            $filter_instansi = (int)$instansi_id;
        }

        $tree = $this->_buildDPAHierarchy($KodeWilayah, $tahun, $filter_instansi);
        echo json_encode(['status' => 'success', 'data' => $tree]);
    }

    public function SaveDPARak() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $KodeWilayah = $this->get_kode_wilayah() ?: $this->input->post('kode_wilayah', TRUE) ?: '35.73';
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $kode_sub_kegiatan = trim($this->input->post('kode_sub_kegiatan', TRUE));
            $header_id = (int)($this->input->post('header_id', TRUE));
            $rincian_list = $this->input->post('rincian');

            if (empty($kode_sub_kegiatan)) {
                throw new Exception('Kode sub kegiatan wajib diisi!');
            }

            // Ambil data header dari belanja_sub_kegiatan_header untuk relasi FK
            $headerRow = null;
            if ($header_id > 0) {
                $headerRow = $this->db->where('id', $header_id)
                                      ->where('deleted_at IS NULL')
                                      ->get('belanja_sub_kegiatan_header')
                                      ->row_array();
            }
            if (!$headerRow) {
                // Fallback: cari header berdasarkan kode_sub_kegiatan + tahun
                $headerRow = $this->db->where('kode_sub_kegiatan', $kode_sub_kegiatan)
                                      ->where('tahun', $tahun)
                                      ->where('deleted_at IS NULL')
                                      ->get('belanja_sub_kegiatan_header')
                                      ->row_array();
            }
            // Gunakan data header untuk kode_wilayah dan id_instansi
            if ($headerRow) {
                $KodeWilayah = $headerRow['kode_wilayah'] ?: $KodeWilayah;
                $header_id = (int)$headerRow['id'];
            }
            $id_instansi = $headerRow ? (int)$headerRow['id_instansi'] : (int)$this->get_instansi_id();

            $normalizeCode = function($code) {
                if (empty($code)) return '';
                $parts = explode('.', trim((string)$code));
                $clean = [];
                foreach ($parts as $p) {
                    $pTrim = trim($p);
                    if (is_numeric($pTrim)) {
                        $clean[] = (string)(int)$pTrim;
                    } else {
                        $clean[] = strtolower($pTrim);
                    }
                }
                return implode('.', $clean);
            };

            // Ambil semua data RAK yang ada untuk sub kegiatan dan tahun ini
            $this->db->select('*')
                ->from('dpa_rak_rincian')
                ->where('tahun', $tahun)
                ->where('deleted_at IS NULL');
            if (!empty($KodeWilayah)) {
                $this->db->where('kode_wilayah', $KodeWilayah);
            }
            $existingRows = $this->db->get()->result_array();
            $normSubKode = $normalizeCode($kode_sub_kegiatan);

            if (!empty($rincian_list) && is_array($rincian_list)) {
                foreach ($rincian_list as $item) {
                    $kode_rek = isset($item['kode']) ? trim($item['kode']) : '';
                    $uraian = isset($item['uraian']) ? trim($item['uraian']) : '';
                    $alokasi = isset($item['alokasi']) ? (float)$item['alokasi'] : 0;
                    $rincian_id = isset($item['id']) && is_numeric($item['id']) ? (int)$item['id'] : null;
                    $jenis = isset($item['jenis']) ? trim($item['jenis']) : 'operasi';
                    $sumber_dana = isset($item['sumberDana']) ? trim($item['sumberDana']) : '';
                    $lokasi = isset($item['lokasi']) ? trim($item['lokasi']) : '';

                    $monthly = isset($item['monthly']) && is_array($item['monthly']) ? $item['monthly'] : array_fill(0, 12, 0);
                    $mVal = [];
                    for ($m = 0; $m < 12; $m++) {
                        $mVal[$m] = isset($monthly[$m]) ? (float)$monthly[$m] : 0;
                    }
                    $total_rak = array_sum($mVal);
                    $selisih = $alokasi - $total_rak;

                    // Cari record yang cocok di database
                    $matchedIds = [];
                    foreach ($existingRows as $er) {
                        $match = false;
                        if ($rincian_id > 0 && !empty($er['rincian_id']) && (int)$er['rincian_id'] === $rincian_id) {
                            $match = true;
                        } else if ($normalizeCode($er['kode_sub_kegiatan']) === $normSubKode && trim($er['kode_rekening']) === $kode_rek) {
                            if (empty($uraian) || empty($er['uraian']) || trim($er['uraian']) === $uraian) {
                                $match = true;
                            }
                        }
                        if ($match) {
                            $matchedIds[] = (int)$er['id'];
                        }
                    }

                    $data_rak = [
                        'header_id' => $header_id > 0 ? $header_id : null,
                        'id_instansi' => $id_instansi > 0 ? $id_instansi : null,
                        'kode_wilayah' => $KodeWilayah,
                        'tahun' => $tahun,
                        'kode_sub_kegiatan' => $kode_sub_kegiatan,
                        'kode_rekening' => $kode_rek,
                        'uraian' => $uraian,
                        'jenis_belanja' => $jenis,
                        'sumber_dana' => $sumber_dana,
                        'lokasi' => $lokasi,
                        'alokasi' => $alokasi,
                        'jan' => $mVal[0],
                        'feb' => $mVal[1],
                        'mar' => $mVal[2],
                        'apr' => $mVal[3],
                        'mei' => $mVal[4],
                        'jun' => $mVal[5],
                        'jul' => $mVal[6],
                        'ags' => $mVal[7],
                        'sep' => $mVal[8],
                        'okt' => $mVal[9],
                        'nov' => $mVal[10],
                        'des' => $mVal[11],
                        'total_rak' => $total_rak,
                        'selisih' => $selisih,
                        'updated_at' => date('Y-m-d H:i:s')
                    ];

                    if (!empty($matchedIds)) {
                        $primaryId = $matchedIds[0];
                        $this->db->where('id', $primaryId)->update('dpa_rak_rincian', $data_rak);

                        // Hapus duplikasi jika ada lebih dari 1 baris
                        if (count($matchedIds) > 1) {
                            $dupIds = array_slice($matchedIds, 1);
                            $this->db->where_in('id', $dupIds)->update('dpa_rak_rincian', ['deleted_at' => date('Y-m-d H:i:s')]);
                        }
                    } else {
                        $data_rak['rincian_id'] = $rincian_id;
                        $data_rak['created_at'] = date('Y-m-d H:i:s');
                        $this->db->insert('dpa_rak_rincian', $data_rak);
                    }
                }
            }

            echo json_encode([
                'status' => 'success',
                'message' => 'Anggaran Kas (RAK) Sub Kegiatan berhasil disimpan!'
            ]);

        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    private function _getUrusanName($kode) {
        $map = [
            "1" => "URUSAN PEMERINTAHAN WAJIB YANG BERKAITAN DENGAN PELAYANAN DASAR",
            "2" => "URUSAN PEMERINTAHAN WAJIB YANG TIDAK BERKAITAN DENGAN PELAYANAN DASAR",
            "3" => "URUSAN PEMERINTAHAN PILIHAN",
            "4" => "UNSUR PENDUKUNG URUSAN PEMERINTAHAN",
            "5" => "UNSUR PENUNJANG URUSAN PEMERINTAHAN",
            "6" => "UNSUR PENGAWASAN URUSAN PEMERINTAHAN",
            "7" => "UNSUR KEWILAYAHAN",
            "8" => "UNSUR PEMERINTAHAN UMUM"
        ];
        return isset($map[$kode]) ? $map[$kode] : "URUSAN PEMERINTAHAN KODE " . $kode;
    }

    private function _getBidangName($kode, $fallback = '') {
        $map = [
            "1.01" => "PENDIDIKAN",
            "1.02" => "KESEHATAN",
            "1.03" => "PEKERJAAN UMUM DAN PENATAAN RUANG",
            "1.04" => "PERUMAHAN RAKYAT DAN KAWASAN PERMUKIMAN",
            "1.05" => "KETENTRAMAN DAN KETERTIBAN UMUM SERTA PERLINDUNGAN MASYARAKAT",
            "1.06" => "SOSIAL",
            "2.09" => "TENAGA KERJA",
            "2.11" => "LINGKUNGAN HIDUP",
            "2.15" => "PERHUBUNGAN",
            "2.16" => "KOMUNIKASI DAN INFORMATIKA",
            "2.17" => "KOPERASI, USAHA KECIL DAN MENENGAH",
            "5.01" => "PERENCANAAN",
            "5.02" => "KEUANGAN",
            "5.03" => "KEPEGAWAIAN, PENDIDIKAN DAN PELATIHAN"
        ];
        if (isset($map[$kode])) return $map[$kode];
        return !empty($fallback) ? strtoupper($fallback) : "BIDANG URUSAN " . $kode;
    }

    private function _buildDPAHierarchy($KodeWilayah, $tahun, $filter_instansi = null) {
        $instRow = null;
        if (!empty($filter_instansi)) {
            $instRow = $this->db->select('id, nama, kode_instansi')->where('id', (int)$filter_instansi)->get('akun_instansi')->row_array();
        }

        // Ambil nama wilayah jika ada
        $namaWilayah = 'Kab. Cirebon';
        if (!empty($KodeWilayah)) {
            $wRow = $this->db->select('Nama')->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            if ($wRow && !empty($wRow['Nama'])) {
                $namaWilayah = $wRow['Nama'];
            }
        }

        // 1. Ambil data dari belanja_sub_kegiatan_header
        $this->db->select('*')
            ->from('belanja_sub_kegiatan_header')
            ->where('deleted_at IS NULL');

        if (!empty($KodeWilayah)) {
            $this->db->where('kode_wilayah', $KodeWilayah);
        }
        if (!empty($tahun) && $tahun !== 'all') {
            $this->db->where('tahun', $tahun);
        }
        if (!empty($filter_instansi)) {
            $this->db->group_start();
            $this->db->where('id_instansi', (int)$filter_instansi);
            if ($instRow && !empty($instRow['nama'])) {
                $this->db->or_where('nama_perangkat_daerah', $instRow['nama']);
            }
            $this->db->group_end();
        }

        $headers = $this->db
            ->order_by('kode_program', 'ASC')
            ->order_by('kode_kegiatan', 'ASC')
            ->order_by('kode_sub_kegiatan', 'ASC')
            ->get()
            ->result_array();

        // 2. Ambil data dari renja_pd_header & renja_pd_detail
        $this->db->select('h.*, d.dpa_murni_rp, d.dpa_perubahan_rp, d.renja_rp, d.sumber_dana, d.lokasi, d.indikator_kinerja, d.satuan')
            ->from('renja_pd_header h')
            ->join('renja_pd_detail d', 'd.header_id = h.id AND d.deleted_at IS NULL', 'left')
            ->where('h.deleted_at IS NULL');

        if (!empty($KodeWilayah)) {
            $this->db->where('h.kode_wilayah', $KodeWilayah);
        }
        if (!empty($tahun) && $tahun !== 'all') {
            $this->db->where('h.tahun', $tahun);
        }
        if (!empty($filter_instansi)) {
            $this->db->where('h.id_instansi', (int)$filter_instansi);
        }

        $renjaRows = $this->db->order_by('h.kode_rekening', 'ASC')->get()->result_array();

        $urusanMap = [];
        $existingSubkeg = [];

        // Ambil semua data RAK tersimpan untuk tahun ini
        $this->db->select('*')->from('dpa_rak_rincian')->where('deleted_at IS NULL');
        if (!empty($tahun) && $tahun !== 'all') {
            $this->db->where('tahun', $tahun);
        }
        if (!empty($KodeWilayah)) {
            $this->db->where('kode_wilayah', $KodeWilayah);
        }
        if (!empty($filter_instansi)) {
            $this->db->where('id_instansi', (int)$filter_instansi);
        }
        $rakSaved = $this->db->get()->result_array();

        $rakMapByRincianId = [];
        $rakMapBySubKegKode = [];
        foreach ($rakSaved as $rs) {
            if (!empty($rs['rincian_id'])) {
                $rakMapByRincianId[$rs['rincian_id']] = $rs;
            }
            $key = $rs['kode_sub_kegiatan'] . '_' . $rs['kode_rekening'];
            $rakMapBySubKegKode[$key] = $rs;
            if (!isset($rakMapBySubKegKode[$rs['kode_sub_kegiatan']])) {
                $rakMapBySubKegKode[$rs['kode_sub_kegiatan']] = $rs;
            }
        }

        // Ambil pemetaan Lokasi & Sumber Dana dari Rankhir Renja (rancangan_akhir_renja_sub_kegiatan_data)
        $rankhirLokasiMap = [];
        $rankhirSumberDanaMap = [];

        $this->db->select('rsk.kode_nomenklatur, rsub.kab_kota, rsub.kecamatan, rsub.desa, rsub.lokasi_pelaksanaan, rsub.sumber_dana')
            ->from('rancangan_akhir_renja_sub_kegiatan_data rsub')
            ->join('renstra_sub_kegiatan rsk', 'rsk.id = rsub.sub_kegiatan_id')
            ->where('rsub.deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('rsub.kode_wilayah', $KodeWilayah);
        if (!empty($tahun) && $tahun !== 'all') $this->db->where('rsub.tahun', $tahun);
        if (!empty($filter_instansi)) $this->db->where('rsub.id_instansi', (int)$filter_instansi);
        $subDataRows = $this->db->get()->result_array();

        if (empty($subDataRows)) {
            $this->db->select('rsk.kode_nomenklatur, rsub.kab_kota, rsub.kecamatan, rsub.desa, rsub.lokasi_pelaksanaan, rsub.sumber_dana')
                ->from('renja_sub_kegiatan_data rsub')
                ->join('renstra_sub_kegiatan rsk', 'rsk.id = rsub.sub_kegiatan_id')
                ->where('rsub.deleted_at IS NULL');
            if (!empty($KodeWilayah)) $this->db->where('rsub.kode_wilayah', $KodeWilayah);
            if (!empty($tahun) && $tahun !== 'all') $this->db->where('rsub.tahun', $tahun);
            if (!empty($filter_instansi)) $this->db->where('rsub.id_instansi', (int)$filter_instansi);
            $subDataRows = $this->db->get()->result_array();
        }

        if (empty($subDataRows)) {
            $this->db->select('rsk.kode_nomenklatur, rsub.kab_kota, rsub.kecamatan, rsub.desa, rsub.lokasi_pelaksanaan, rsub.sumber_dana')
                ->from('rancangan_renja_sub_kegiatan_data rsub')
                ->join('renstra_sub_kegiatan rsk', 'rsk.id = rsub.sub_kegiatan_id')
                ->where('rsub.deleted_at IS NULL');
            if (!empty($KodeWilayah)) $this->db->where('rsub.kode_wilayah', $KodeWilayah);
            if (!empty($tahun) && $tahun !== 'all') $this->db->where('rsub.tahun', $tahun);
            if (!empty($filter_instansi)) $this->db->where('rsub.id_instansi', (int)$filter_instansi);
            $subDataRows = $this->db->get()->result_array();
        }

        foreach ($subDataRows as $sdr) {
            $skKode = trim($sdr['kode_nomenklatur'] ?? '');
            if (!$skKode) continue;
            $kab = trim($sdr['kab_kota'] ?? '');
            $kec = trim($sdr['kecamatan'] ?? '');
            $desa = trim($sdr['desa'] ?? '');
            $lok = trim($sdr['lokasi_pelaksanaan'] ?? '');

            $lokText = '';
            if ($desa && $kec && $kab) {
                $lokText = "$kab, Kec. $kec, $desa";
            } elseif ($kec && $kab) {
                $lokText = "$kab, Kec. $kec";
            } elseif ($kab) {
                $lokText = $kab;
            } elseif ($lok) {
                $lokText = $lok;
            }

            if ($lokText) {
                $rankhirLokasiMap[$skKode] = $lokText;
            }
            if (!empty($sdr['sumber_dana'])) {
                $rankhirSumberDanaMap[$skKode] = $sdr['sumber_dana'];
            }
        }

        // Proses dari Belanja Sub Kegiatan Header
        if (!empty($headers)) {
            $headerIds = array_column($headers, 'id');
            $rekenings = $this->db
                ->where_in('header_id', $headerIds)
                ->where('deleted_at IS NULL')
                ->order_by('kode_rekening', 'ASC')
                ->get('belanja_rekening')
                ->result_array();

            $rincianList = [];
            if (!empty($rekenings)) {
                $rekIds = array_column($rekenings, 'id');
                $rincianRows = $this->db
                    ->where_in('rekening_id', $rekIds)
                    ->where('deleted_at IS NULL')
                    ->order_by('id', 'ASC')
                    ->get('belanja_rincian')
                    ->result_array();

                foreach ($rincianRows as $rinc) {
                    $rincianList[$rinc['rekening_id']][] = $rinc;
                }
            }

            $rekeningByHeader = [];
            foreach ($rekenings as $rek) {
                $rek['rincian'] = isset($rincianList[$rek['id']]) ? $rincianList[$rek['id']] : [];
                $rekeningByHeader[$rek['header_id']][] = $rek;
            }

            foreach ($headers as $h) {
                $subKegKode = $h['kode_sub_kegiatan'] ?: '5.01.01.1.01.01';
                $kegKode = $h['kode_kegiatan'] ?: substr($subKegKode, 0, 13);
                $progKode = $h['kode_program'] ?: substr($kegKode, 0, 7);
                $bidangKode = $h['kode_bidang_urusan'] ?: substr($progKode, 0, 4);
                $urusanKode = substr($bidangKode, 0, 1);

                $existingSubkeg[$subKegKode] = true;

                $lokasiSubKeg = isset($rankhirLokasiMap[$subKegKode]) ? $rankhirLokasiMap[$subKegKode] : ($namaWilayah . ', Semua Kecamatan, Semua Kelurahan/Desa');
                $sumberDanaSubKeg = isset($rankhirSumberDanaMap[$subKegKode]) ? $rankhirSumberDanaMap[$subKegKode] : 'Pendapatan Asli Daerah (PAD)';

                if (!isset($urusanMap[$urusanKode])) {
                    $urusanMap[$urusanKode] = [
                        'kode' => $urusanKode,
                        'uraian' => $this->_getUrusanName($urusanKode),
                        'bidang' => []
                    ];
                }

                if (!isset($urusanMap[$urusanKode]['bidang'][$bidangKode])) {
                    $urusanMap[$urusanKode]['bidang'][$bidangKode] = [
                        'kode' => $bidangKode,
                        'uraian' => $this->_getBidangName($bidangKode, $h['nama_bidang_urusan']),
                        'program' => []
                    ];
                }

                if (!isset($urusanMap[$urusanKode]['bidang'][$bidangKode]['program'][$progKode])) {
                    $urusanMap[$urusanKode]['bidang'][$bidangKode]['program'][$progKode] = [
                        'kode' => $progKode,
                        'uraian' => $h['nama_program'] ?: 'PROGRAM ' . $progKode,
                        'kegiatan' => []
                    ];
                }

                if (!isset($urusanMap[$urusanKode]['bidang'][$bidangKode]['program'][$progKode]['kegiatan'][$kegKode])) {
                    $urusanMap[$urusanKode]['bidang'][$bidangKode]['program'][$progKode]['kegiatan'][$kegKode] = [
                        'kode' => $kegKode,
                        'uraian' => $h['nama_kegiatan'] ?: 'KEGIATAN ' . $kegKode,
                        'subKegiatan' => []
                    ];
                }

                // Format rincian items
                $rList = [];
                $hReks = isset($rekeningByHeader[$h['id']]) ? $rekeningByHeader[$h['id']] : [];
                foreach ($hReks as $rek) {
                    $rekRincs = isset($rek['rincian']) ? $rek['rincian'] : [];
                    foreach ($rekRincs as $rinc) {
                        $rId = (int)$rinc['id'];
                        $m = array_fill(0, 12, 0);

                        $kKey = $subKegKode . '_' . $rek['kode_rekening'];
                        $rakRow = isset($rakMapByRincianId[$rId]) ? $rakMapByRincianId[$rId] : (isset($rakMapBySubKegKode[$kKey]) ? $rakMapBySubKegKode[$kKey] : null);
                        
                        if ($rakRow) {
                            $m = [
                                (float)$rakRow['jan'], (float)$rakRow['feb'], (float)$rakRow['mar'],
                                (float)$rakRow['apr'], (float)$rakRow['mei'], (float)$rakRow['jun'],
                                (float)$rakRow['jul'], (float)$rakRow['ags'], (float)$rakRow['sep'],
                                (float)$rakRow['okt'], (float)$rakRow['nov'], (float)$rakRow['des']
                            ];
                        }

                        $rList[] = [
                            'id' => $rId,
                            'kode' => $rek['kode_rekening'],
                            'uraian' => $rinc['uraian'] ?: ($rinc['komponen'] ?: $rek['uraian_rekening']),
                            'jenis' => (strpos($rek['kode_rekening'], '5.2') === 0) ? 'modal' : ((strpos($rek['kode_rekening'], '5.3') === 0) ? 'tidakTerduga' : ((strpos($rek['kode_rekening'], '5.4') === 0) ? 'transfer' : 'operasi')),
                            'sumberDana' => $sumberDanaSubKeg ?: ($rinc['sumber_dana'] ?: 'Pendapatan Asli Daerah (PAD)'),
                            'lokasi' => $lokasiSubKeg,
                            'alokasi' => (float)$rinc['jumlah'],
                            'monthly' => $m
                        ];
                    }
                }

                $subKegData = [
                    'id' => $h['id'],
                    'headerId' => (int)$h['id'],
                    'idInstansi' => (int)$h['id_instansi'],
                    'kode' => $subKegKode,
                    'uraian' => $h['nama_sub_kegiatan'] ?: 'Sub Kegiatan ' . $subKegKode,
                    'perangkatDaerah' => $h['nama_perangkat_daerah'] ?: ($instRow ? $instRow['nama'] : ''),
                    'sumberDana' => $sumberDanaSubKeg ?: (count($rList) > 0 && !empty($rList[0]['sumberDana']) ? $rList[0]['sumberDana'] : 'Pendapatan Asli Daerah (PAD)'),
                    'lokasi' => $lokasiSubKeg,
                    'totalBelanja' => (float)$h['total_belanja'],
                    'flagged' => false,
                    'rincian' => $rList
                ];

                $urusanMap[$urusanKode]['bidang'][$bidangKode]['program'][$progKode]['kegiatan'][$kegKode]['subKegiatan'][] = $subKegData;
            }
        }

        // Convert associative maps to clean arrays
        $result = [];
        foreach ($urusanMap as $u) {
            $uItem = ['kode' => $u['kode'], 'uraian' => $u['uraian'], 'bidang' => []];
            foreach ($u['bidang'] as $b) {
                $bItem = ['kode' => $b['kode'], 'uraian' => $b['uraian'], 'program' => []];
                foreach ($b['program'] as $p) {
                    $pItem = ['kode' => $p['kode'], 'uraian' => $p['uraian'], 'kegiatan' => []];
                    foreach ($p['kegiatan'] as $k) {
                        $kItem = ['kode' => $k['kode'], 'uraian' => $k['uraian'], 'subKegiatan' => $k['subKegiatan']];
                        $pItem['kegiatan'][] = $kItem;
                    }
                    $bItem['program'][] = $pItem;
                }
                $uItem['bidang'][] = $bItem;
            }
            $result[] = $uItem;
        }

        return $result;
    }

    // ================================================================
    // TARGET RENAKSI (RENCANA AKSI & TARGET KINERJA)
    // ================================================================

    public function TargetRenaksi() {
        $Header['Halaman'] = 'Target Renaksi';
        
        $KodeWilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        $is_role_4 = $this->is_role_4();
        $tahun = (int)($this->input->get('tahun', TRUE) ?: (isset($_SESSION['Tahun']) ? $_SESSION['Tahun'] : 2026));
        $filter_instansi = $this->input->get('instansi_id', TRUE);
        if (empty($filter_instansi) && isset($_SESSION['TempInstansiId']) && !empty($_SESSION['TempInstansiId'])) {
            $filter_instansi = $_SESSION['TempInstansiId'];
        }
        
        // Data Provinsi untuk filter
        $Data['Provinsi'] = $this->db
            ->where("Kode LIKE '__'")
            ->order_by('Nama')
            ->get('kodewilayah')
            ->result_array();
        
        $is_logged_in = $this->is_logged_in();
        $Data['IsLoggedIn'] = $is_logged_in;
        $Data['KodeWilayah'] = $KodeWilayah;
        $Data['NamaWilayah'] = '';
        $Data['IsRole4'] = $is_role_4;
        $Data['IsDaerah'] = $is_logged_in && !$is_role_4;
        $Data['InstansiId'] = $instansi_id;
        $Data['ControllerName'] = 'Instansi';
        
        // Ambil Nama Wilayah jika ada
        if (!empty($KodeWilayah)) {
            $wilayah = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            $Data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
        }
        
        // List Instansi
        $Data['ListInstansi'] = [];
        if (!empty($KodeWilayah)) {
            $provKode = substr($KodeWilayah, 0, 2);
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where("(kodewilayah = " . $this->db->escape($KodeWilayah) . " OR kodewilayah = " . $this->db->escape($provKode) . ")")
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        } else {
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        }
        
        if ($is_role_4 && $instansi_id) {
            $filter_instansi = $instansi_id;
        } elseif (empty($filter_instansi) && !empty($Data['ListInstansi'])) {
            $filter_instansi = (int)$Data['ListInstansi'][0]['id'];
        }

        // List Tahun
        $dbYears = $this->db->select('DISTINCT(tahun) as thn')
            ->where('deleted_at IS NULL')
            ->order_by('tahun', 'DESC')
            ->get('belanja_sub_kegiatan_header')
            ->result_array();
        
        $listTahun = [2026, 2027, 2028, 2029, 2030];
        if (!empty($dbYears)) {
            foreach ($dbYears as $dy) {
                if (!empty($dy['thn']) && !in_array((int)$dy['thn'], $listTahun)) {
                    $listTahun[] = (int)$dy['thn'];
                }
            }
        }
        rsort($listTahun);
        $Data['ListTahun'] = $listTahun;
        
        $Data['TahunAktif'] = $tahun;
        $Data['FilterInstansi'] = $filter_instansi;

        // Ambil Data Hierarki Target Renaksi
        if (!$is_logged_in && empty($KodeWilayah)) {
            $Data['RenaksiTree'] = [];
        } else {
            $Data['RenaksiTree'] = $this->_buildTargetRenaksiHierarchy($KodeWilayah, $tahun, $filter_instansi);
        }
        
        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/TargetRenaksi', $Data);
    }

    public function GetTargetRenaksiData() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $KodeWilayah = $this->get_kode_wilayah();
        $is_role_4 = $this->is_role_4();
        $instansi_id = $this->get_instansi_id();
        $tahun = (int)($this->input->post('tahun', TRUE) ?: (isset($_SESSION['Tahun']) ? $_SESSION['Tahun'] : 2026));
        $filter_instansi = $this->input->post('instansi', TRUE);

        if (empty($filter_instansi) && isset($_SESSION['TempInstansiId']) && !empty($_SESSION['TempInstansiId'])) {
            $filter_instansi = $_SESSION['TempInstansiId'];
        }

        if ($is_role_4 && $instansi_id) {
            $filter_instansi = $instansi_id;
        }

        $tree = $this->_buildTargetRenaksiHierarchy($KodeWilayah, $tahun, $filter_instansi);
        echo json_encode(['status' => 'success', 'data' => $tree]);
    }

    public function GetSubKegiatanTargetDetail() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $header_id = (int)$this->input->post('header_id', TRUE);
        $kode_sub_kegiatan = trim($this->input->post('kode_sub_kegiatan', TRUE));
        $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));

        $this->db->where('deleted_at IS NULL');
        if ($header_id > 0) {
            $this->db->where('id', $header_id);
        } else if (!empty($kode_sub_kegiatan)) {
            $this->db->where('kode_sub_kegiatan', $kode_sub_kegiatan)->where('tahun', $tahun);
        }
        $header = $this->db->get('belanja_sub_kegiatan_header')->row_array();

        if (!$header) {
            echo json_encode(['status' => 'error', 'message' => 'Data Sub Kegiatan tidak ditemukan.']);
            return;
        }

        $hId = (int)$header['id'];
        $subKode = $header['kode_sub_kegiatan'];
        $thn = (int)$header['tahun'];

        // Indikator Sub Kegiatan
        $indikators = $this->db
            ->where('deleted_at IS NULL')
            ->group_start()
                ->where('header_id', $hId)
                ->or_group_start()
                    ->where('entity_code', $subKode)
                    ->where('tahun', $thn)
                ->group_end()
            ->group_end()
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get('target_renaksi_indikator')
            ->result_array();

        // Target Anggaran Bulanan
        $anggaran = $this->db
            ->where('deleted_at IS NULL')
            ->group_start()
                ->where('header_id', $hId)
                ->or_group_start()
                    ->where('kode_sub_kegiatan', $subKode)
                    ->where('tahun', $thn)
                ->group_end()
            ->group_end()
            ->get('target_renaksi_anggaran_bulanan')
            ->row_array();

        // Fallback RAK DPA jika anggaran renaksi belum tersimpan
        if (!$anggaran) {
            $rakRows = $this->db
                ->where('tahun', $thn)
                ->where('kode_sub_kegiatan', $subKode)
                ->where('deleted_at IS NULL')
                ->get('dpa_rak_rincian')
                ->result_array();

            $m = array_fill(0, 12, 0);
            $totalRak = 0;
            if (!empty($rakRows)) {
                foreach ($rakRows as $r) {
                    $m[0] += (float)$r['jan'];
                    $m[1] += (float)$r['feb'];
                    $m[2] += (float)$r['mar'];
                    $m[3] += (float)$r['apr'];
                    $m[4] += (float)$r['mei'];
                    $m[5] += (float)$r['jun'];
                    $m[6] += (float)$r['jul'];
                    $m[7] += (float)$r['ags'];
                    $m[8] += (float)$r['sep'];
                    $m[9] += (float)$r['okt'];
                    $m[10] += (float)$r['nov'];
                    $m[11] += (float)$r['des'];
                    $totalRak += (float)$r['total_rak'];
                }
            } else {
                $totalRak = (float)$header['total_belanja'];
            }

            $anggaran = [
                'jan' => $m[0], 'feb' => $m[1], 'mar' => $m[2], 'apr' => $m[3],
                'mei' => $m[4], 'jun' => $m[5], 'jul' => $m[6], 'ags' => $m[7],
                'sep' => $m[8], 'okt' => $m[9], 'nov' => $m[10], 'des' => $m[11],
                'total_anggaran' => $totalRak
            ];
        }

        // Tahapan Proses
        $tahapan = $this->db
            ->where('deleted_at IS NULL')
            ->group_start()
                ->where('header_id', $hId)
                ->or_group_start()
                    ->where('kode_sub_kegiatan', $subKode)
                    ->where('tahun', $thn)
                ->group_end()
            ->group_end()
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get('target_renaksi_tahapan_proses')
            ->result_array();

        echo json_encode([
            'status' => 'success',
            'data' => [
                'header' => $header,
                'indikators' => $indikators,
                'anggaranBulanan' => $anggaran,
                'tahapanProses' => $tahapan
            ]
        ]);
    }

    public function SaveTargetRenaksiSubKegiatan() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $header_id = (int)$this->input->post('header_id', TRUE);
            $kode_sub_kegiatan = trim($this->input->post('kode_sub_kegiatan', TRUE));
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: $this->get_kode_wilayah() ?: '35.73';
            $id_instansi = (int)($this->input->post('id_instansi', TRUE) ?: $this->get_instansi_id() ?: 1);

            $header = null;
            if ($header_id > 0) {
                $header = $this->db->where('id', $header_id)->where('deleted_at IS NULL')->get('belanja_sub_kegiatan_header')->row_array();
            }
            if (!$header && !empty($kode_sub_kegiatan)) {
                $header = $this->db->where('kode_sub_kegiatan', $kode_sub_kegiatan)->where('tahun', $tahun)->where('deleted_at IS NULL')->get('belanja_sub_kegiatan_header')->row_array();
            }

            if ($header) {
                $header_id = (int)$header['id'];
                $kode_sub_kegiatan = $header['kode_sub_kegiatan'];
                $kode_wilayah = $header['kode_wilayah'] ?: $kode_wilayah;
                $id_instansi = $header['id_instansi'] ? (int)$header['id_instansi'] : $id_instansi;
            }

            $indikators = $this->input->post('indikators');
            $anggaran = $this->input->post('anggaran_bulanan');
            $tahapan = $this->input->post('tahapan_proses');

            $this->db->trans_begin();
            $now = date('Y-m-d H:i:s');

            // 1. Simpan Anggaran Bulanan
            if (!empty($anggaran) && is_array($anggaran)) {
                $mJan = isset($anggaran['jan']) ? (float)$anggaran['jan'] : 0;
                $mFeb = isset($anggaran['feb']) ? (float)$anggaran['feb'] : 0;
                $mMar = isset($anggaran['mar']) ? (float)$anggaran['mar'] : 0;
                $mApr = isset($anggaran['apr']) ? (float)$anggaran['apr'] : 0;
                $mMei = isset($anggaran['mei']) ? (float)$anggaran['mei'] : 0;
                $mJun = isset($anggaran['jun']) ? (float)$anggaran['jun'] : 0;
                $mJul = isset($anggaran['jul']) ? (float)$anggaran['jul'] : 0;
                $mAgs = isset($anggaran['ags']) ? (float)$anggaran['ags'] : (isset($anggaran['agu']) ? (float)$anggaran['agu'] : 0);
                $mSep = isset($anggaran['sep']) ? (float)$anggaran['sep'] : 0;
                $mOkt = isset($anggaran['okt']) ? (float)$anggaran['okt'] : 0;
                $mNov = isset($anggaran['nov']) ? (float)$anggaran['nov'] : 0;
                $mDes = isset($anggaran['des']) ? (float)$anggaran['des'] : 0;
                $totAng = $mJan + $mFeb + $mMar + $mApr + $mMei + $mJun + $mJul + $mAgs + $mSep + $mOkt + $mNov + $mDes;

                $existAng = null;
                if ($header_id > 0) {
                    $existAng = $this->db
                        ->where('deleted_at IS NULL')
                        ->where('header_id', $header_id)
                        ->where('tahun', $tahun)
                        ->get('target_renaksi_anggaran_bulanan')
                        ->row_array();
                }
                if (!$existAng && !empty($kode_sub_kegiatan)) {
                    $this->db
                        ->where('deleted_at IS NULL')
                        ->where('kode_sub_kegiatan', $kode_sub_kegiatan)
                        ->where('tahun', $tahun);
                    if ($id_instansi > 0) {
                        $this->db->where('id_instansi', $id_instansi);
                    }
                    $existAng = $this->db->get('target_renaksi_anggaran_bulanan')->row_array();
                }

                $angData = [
                    'header_id' => $header_id,
                    'kode_wilayah' => $kode_wilayah,
                    'tahun' => $tahun,
                    'id_instansi' => $id_instansi,
                    'kode_sub_kegiatan' => $kode_sub_kegiatan,
                    'jan' => $mJan, 'feb' => $mFeb, 'mar' => $mMar, 'apr' => $mApr,
                    'mei' => $mMei, 'jun' => $mJun, 'jul' => $mJul, 'ags' => $mAgs,
                    'sep' => $mSep, 'okt' => $mOkt, 'nov' => $mNov, 'des' => $mDes,
                    'total_anggaran' => $totAng,
                    'updated_at' => $now
                ];

                if ($existAng) {
                    $this->db->where('id', $existAng['id'])->update('target_renaksi_anggaran_bulanan', $angData);
                } else {
                    $angData['created_at'] = $now;
                    $this->db->insert('target_renaksi_anggaran_bulanan', $angData);
                }
            }

            // 2. Simpan Indikators
            $savedIndikatorIds = [];
            $indCount = 0;
            if (!empty($indikators) && is_array($indikators)) {
                $indCount = count($indikators);
                foreach ($indikators as $idx => $ind) {
                    $indId = isset($ind['id']) && is_numeric($ind['id']) ? (int)$ind['id'] : 0;
                    $uraian = isset($ind['uraian']) ? trim($ind['uraian']) : (isset($ind['nama']) ? trim($ind['nama']) : '');
                    $satuan = isset($ind['satuan']) ? trim($ind['satuan']) : '';
                    $targetTahunan = isset($ind['targetTahunan']) ? (float)str_replace(',', '.', trim((string)$ind['targetTahunan'])) : (isset($ind['target_tahunan']) ? (float)str_replace(',', '.', trim((string)$ind['target_tahunan'])) : 0);
                    $tw1 = (isset($ind['tw1']) && $ind['tw1'] !== '' && $ind['tw1'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw1'])) : null;
                    $tw2 = (isset($ind['tw2']) && $ind['tw2'] !== '' && $ind['tw2'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw2'])) : null;
                    $tw3 = (isset($ind['tw3']) && $ind['tw3'] !== '' && $ind['tw3'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw3'])) : null;
                    $tw4 = (isset($ind['tw4']) && $ind['tw4'] !== '' && $ind['tw4'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw4'])) : null;

                    if (empty($uraian)) continue;

                    // Hitung Validitas: TW sum vs Target Tahunan
                    $sumTw = ($tw1 ?: 0) + ($tw2 ?: 0) + ($tw3 ?: 0) + ($tw4 ?: 0);
                    $validitas = (abs($sumTw - $targetTahunan) < 0.0001) ? 'Valid' : 'Invalid';

                    $indRow = [
                        'header_id' => $header_id,
                        'kode_wilayah' => $kode_wilayah,
                        'tahun' => $tahun,
                        'id_instansi' => $id_instansi,
                        'level_type' => 'sub_kegiatan',
                        'entity_code' => $kode_sub_kegiatan,
                        'entity_name' => $header ? $header['nama_sub_kegiatan'] : '',
                        'uraian_indikator' => $uraian,
                        'satuan' => $satuan,
                        'target_tahunan' => $targetTahunan,
                        'tw1' => $tw1,
                        'tw2' => $tw2,
                        'tw3' => $tw3,
                        'tw4' => $tw4,
                        'validitas' => $validitas,
                        'urutan' => $idx + 1,
                        'updated_at' => $now
                    ];

                    if ($indId > 0) {
                        $this->db->where('id', $indId)->update('target_renaksi_indikator', $indRow);
                        $savedIndikatorIds[] = $indId;
                    } else {
                        $indRow['created_at'] = $now;
                        $this->db->insert('target_renaksi_indikator', $indRow);
                        $savedIndikatorIds[] = $this->db->insert_id();
                    }
                }

                // Hapus indikator lama yang tidak ada lagi di submit
                if (!empty($savedIndikatorIds)) {
                    $this->db->where('level_type', 'sub_kegiatan')
                        ->group_start()
                            ->where('header_id', $header_id)
                            ->or_group_start()
                                ->where('entity_code', $kode_sub_kegiatan)
                                ->where('tahun', $tahun)
                            ->group_end()
                        ->group_end()
                        ->where_not_in('id', $savedIndikatorIds)
                        ->update('target_renaksi_indikator', ['deleted_at' => $now]);
                }
            }

            // 3. Simpan Tahapan Proses
            $savedTahapIds = [];
            if (!empty($tahapan) && is_array($tahapan)) {
                foreach ($tahapan as $tidx => $tp) {
                    $tId = isset($tp['id']) && is_numeric($tp['id']) ? (int)$tp['id'] : 0;
                    $tpUraian = isset($tp['uraian']) ? trim($tp['uraian']) : (isset($tp['uraian_tahapan_proses']) ? trim($tp['uraian_tahapan_proses']) : '');
                    $tpNilai = isset($tp['nilai']) ? (float)str_replace(',', '.', trim((string)$tp['nilai'])) : (isset($tp['target_output_nilai']) ? (float)str_replace(',', '.', trim((string)$tp['target_output_nilai'])) : 0);
                    $tpSatuan = isset($tp['satuan']) ? trim($tp['satuan']) : (isset($tp['target_output_satuan']) ? trim($tp['target_output_satuan']) : '');
                    $tpBobot = isset($tp['bobot']) ? (float)str_replace(',', '.', trim((string)$tp['bobot'])) : (isset($tp['bobot_kinerja']) ? (float)str_replace(',', '.', trim((string)$tp['bobot_kinerja'])) : 0);
                    $tpBulan = isset($tp['bulan']) ? (int)$tp['bulan'] : (isset($tp['rencana_bulan']) ? (int)$tp['rencana_bulan'] : 1);

                    if (empty($tpUraian)) continue;

                    $tpRow = [
                        'header_id' => $header_id,
                        'indikator_id' => isset($savedIndikatorIds[0]) ? $savedIndikatorIds[0] : null,
                        'kode_wilayah' => $kode_wilayah,
                        'tahun' => $tahun,
                        'id_instansi' => $id_instansi,
                        'kode_sub_kegiatan' => $kode_sub_kegiatan,
                        'uraian_tahapan_proses' => $tpUraian,
                        'target_output_nilai' => $tpNilai,
                        'target_output_satuan' => $tpSatuan,
                        'bobot_kinerja' => $tpBobot,
                        'rencana_bulan' => $tpBulan,
                        'urutan' => $tidx + 1,
                        'updated_at' => $now
                    ];

                    if ($tId > 0) {
                        $this->db->where('id', $tId)->update('target_renaksi_tahapan_proses', $tpRow);
                        $savedTahapIds[] = $tId;
                    } else {
                        $tpRow['created_at'] = $now;
                        $this->db->insert('target_renaksi_tahapan_proses', $tpRow);
                        $savedTahapIds[] = $this->db->insert_id();
                    }
                }

                if (!empty($savedTahapIds)) {
                    $this->db->group_start()
                            ->where('header_id', $header_id)
                            ->or_group_start()
                                ->where('kode_sub_kegiatan', $kode_sub_kegiatan)
                                ->where('tahun', $tahun)
                            ->group_end()
                        ->group_end()
                        ->where_not_in('id', $savedTahapIds)
                        ->update('target_renaksi_tahapan_proses', ['deleted_at' => $now]);
                }
            }

            if ($this->db->trans_status() === FALSE) {
                $this->db->trans_rollback();
                throw new Exception('Gagal menyimpan target renaksi sub kegiatan.');
            } else {
                $this->db->trans_commit();
                echo json_encode([
                    'status' => 'success',
                    'message' => 'Target Renaksi Sub Kegiatan berhasil disimpan!'
                ]);
            }
        } catch (Exception $e) {
            $this->db->trans_rollback();
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    public function SaveTargetRenaksiHierarchy() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $level_type = trim($this->input->post('level_type', TRUE));
            $entity_code = trim($this->input->post('entity_code', TRUE));
            $entity_name = trim($this->input->post('entity_name', TRUE));
            $nomenklatur = trim($this->input->post('nomenklatur', TRUE));
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: $this->get_kode_wilayah() ?: '35.73';
            $id_instansi = (int)($this->input->post('id_instansi', TRUE) ?: $this->get_instansi_id() ?: 1);

            $indikators = $this->input->post('indikators');

            $this->db->trans_begin();
            $now = date('Y-m-d H:i:s');

            if (!empty($indikators) && is_array($indikators)) {
                foreach ($indikators as $idx => $ind) {
                    $indId = isset($ind['id']) && is_numeric($ind['id']) ? (int)$ind['id'] : 0;
                    $nama = isset($ind['nama']) ? trim($ind['nama']) : '';
                    $satuan = isset($ind['satuan']) ? trim($ind['satuan']) : '';
                    $targetTahunan = isset($ind['targetTahunan']) ? (float)str_replace(',', '.', trim((string)$ind['targetTahunan'])) : 0;
                    $tw1 = (isset($ind['tw1']) && $ind['tw1'] !== '' && $ind['tw1'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw1'])) : null;
                    $tw2 = (isset($ind['tw2']) && $ind['tw2'] !== '' && $ind['tw2'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw2'])) : null;
                    $tw3 = (isset($ind['tw3']) && $ind['tw3'] !== '' && $ind['tw3'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw3'])) : null;
                    $tw4 = (isset($ind['tw4']) && $ind['tw4'] !== '' && $ind['tw4'] !== null) ? (float)str_replace(',', '.', trim((string)$ind['tw4'])) : null;

                    if (empty($nama) && $indId <= 0) continue;

                    $hierRow = [
                        'kode_wilayah' => $kode_wilayah,
                        'tahun' => $tahun,
                        'id_instansi' => $id_instansi,
                        'level_type' => $level_type,
                        'entity_code' => $entity_code,
                        'entity_name' => $entity_name,
                        'nomenklatur' => $nomenklatur,
                        'indikator_nama' => $nama,
                        'satuan' => $satuan,
                        'target_tahunan' => $targetTahunan,
                        'tw1' => $tw1,
                        'tw2' => $tw2,
                        'tw3' => $tw3,
                        'tw4' => $tw4,
                        'urutan' => $idx + 1,
                        'updated_at' => $now
                    ];

                    if ($indId > 0) {
                        $this->db->where('id', $indId)->update('target_renaksi_hierarchy', $hierRow);
                    } else {
                        $exist = $this->db->where('level_type', $level_type)
                            ->where('entity_code', $entity_code)
                            ->where('indikator_nama', $nama)
                            ->where('tahun', $tahun)
                            ->where('deleted_at IS NULL')
                            ->get('target_renaksi_hierarchy')
                            ->row_array();

                        if ($exist) {
                            $this->db->where('id', $exist['id'])->update('target_renaksi_hierarchy', $hierRow);
                        } else {
                            $hierRow['created_at'] = $now;
                            $this->db->insert('target_renaksi_hierarchy', $hierRow);
                        }
                    }
                }
            }

            if ($this->db->trans_status() === FALSE) {
                $this->db->trans_rollback();
                throw new Exception('Gagal menyimpan target hierarki.');
            } else {
                $this->db->trans_commit();
                echo json_encode([
                    'status' => 'success',
                    'message' => 'Target Kinerja Triwulan berhasil disimpan!'
                ]);
            }
        } catch (Exception $e) {
            $this->db->trans_rollback();
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    public function SyncDPAAnggaran() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $instansi_id = $this->input->post('instansi_id', TRUE);
            $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: ($this->get_kode_wilayah() ?: '35.73');

            $this->db->trans_begin();
            $now = date('Y-m-d H:i:s');

            // 1. Reset custom edits di tabel Target Renaksi
            $this->db->where('tahun', $tahun);
            if (!empty($instansi_id)) {
                $this->db->where('id_instansi', (int)$instansi_id);
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $this->db->update('target_renaksi_hierarchy', ['deleted_at' => $now]);

            $this->db->where('tahun', $tahun);
            if (!empty($instansi_id)) {
                $this->db->where('id_instansi', (int)$instansi_id);
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $this->db->update('target_renaksi_indikator', ['deleted_at' => $now]);

            $this->db->where('tahun', $tahun);
            if (!empty($instansi_id)) {
                $this->db->where('id_instansi', (int)$instansi_id);
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $this->db->update('target_renaksi_tahapan_proses', ['deleted_at' => $now]);

            $this->db->where('tahun', $tahun);
            if (!empty($instansi_id)) {
                $this->db->where('id_instansi', (int)$instansi_id);
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $this->db->update('target_renaksi_anggaran_bulanan', ['deleted_at' => $now]);

            $normalizeCode = function($code) {
                if (empty($code)) return '';
                $parts = explode('.', trim((string)$code));
                $clean = [];
                foreach ($parts as $p) {
                    $pTrim = trim($p);
                    if (is_numeric($pTrim)) {
                        $clean[] = (string)(int)$pTrim;
                    } else {
                        $clean[] = strtolower($pTrim);
                    }
                }
                return implode('.', $clean);
            };

            // 2. Tarik data RAK dari DPA
            $this->db->select('*')->from('dpa_rak_rincian')->where('deleted_at IS NULL')->where('tahun', $tahun);
            if (!empty($instansi_id)) {
                $this->db->group_start()
                    ->where('id_instansi', (int)$instansi_id)
                    ->or_where('id_instansi IS NULL')
                    ->or_where('id_instansi', 0)
                ->group_end();
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $allRakRows = $this->db->order_by('id', 'ASC')->get()->result_array();

            $uniqueRakRows = [];
            foreach ($allRakRows as $r) {
                $rKey = '';
                if (!empty($r['rincian_id'])) {
                    $rKey = 'r_' . $r['rincian_id'];
                } else {
                    $rKey = 'k_' . $normalizeCode($r['kode_sub_kegiatan']) . '_' . trim($r['kode_rekening'] ?? '') . '_' . trim($r['uraian'] ?? '');
                }
                $uniqueRakRows[$rKey] = $r;
            }

            $rakByNormCode = [];
            foreach ($uniqueRakRows as $r) {
                $rSk = trim($r['kode_sub_kegiatan'] ?? '');
                $rNorm = $normalizeCode($rSk);
                if (empty($rNorm)) continue;

                if (!isset($rakByNormCode[$rNorm])) {
                    $rakByNormCode[$rNorm] = [
                        'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                        'mei' => 0, 'jun' => 0, 'jul' => 0, 'ags' => 0,
                        'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
                        'total' => 0
                    ];
                }
                $rakByNormCode[$rNorm]['jan'] += (float)($r['jan'] ?? 0);
                $rakByNormCode[$rNorm]['feb'] += (float)($r['feb'] ?? 0);
                $rakByNormCode[$rNorm]['mar'] += (float)($r['mar'] ?? 0);
                $rakByNormCode[$rNorm]['apr'] += (float)($r['apr'] ?? 0);
                $rakByNormCode[$rNorm]['mei'] += (float)($r['mei'] ?? 0);
                $rakByNormCode[$rNorm]['jun'] += (float)($r['jun'] ?? 0);
                $rakByNormCode[$rNorm]['jul'] += (float)($r['jul'] ?? 0);
                $rakByNormCode[$rNorm]['ags'] += (float)($r['ags'] ?? ($r['agu'] ?? 0));
                $rakByNormCode[$rNorm]['sep'] += (float)($r['sep'] ?? 0);
                $rakByNormCode[$rNorm]['okt'] += (float)($r['okt'] ?? 0);
                $rakByNormCode[$rNorm]['nov'] += (float)($r['nov'] ?? 0);
                $rakByNormCode[$rNorm]['des'] += (float)($r['des'] ?? 0);

                $mTot = (float)($r['jan'] ?? 0) + (float)($r['feb'] ?? 0) + (float)($r['mar'] ?? 0) + (float)($r['apr'] ?? 0) + 
                        (float)($r['mei'] ?? 0) + (float)($r['jun'] ?? 0) + (float)($r['jul'] ?? 0) + (float)($r['ags'] ?? ($r['agu'] ?? 0)) + 
                        (float)($r['sep'] ?? 0) + (float)($r['okt'] ?? 0) + (float)($r['nov'] ?? 0) + (float)($r['des'] ?? 0);
                $rakByNormCode[$rNorm]['total'] += (float)($r['total_rak'] ?? 0) > 0 ? (float)$r['total_rak'] : $mTot;
            }

            $this->db->where('tahun', $tahun)->where('deleted_at IS NULL');
            if (!empty($instansi_id)) {
                $this->db->where('id_instansi', (int)$instansi_id);
            }
            if (!empty($kode_wilayah)) {
                $this->db->where('kode_wilayah', $kode_wilayah);
            }
            $headers = $this->db->get('belanja_sub_kegiatan_header')->result_array();

            $syncedCount = 0;

            foreach ($headers as $h) {
                $hId = (int)$h['id'];
                $subKode = $h['kode_sub_kegiatan'];
                $subNorm = $normalizeCode($subKode);

                $rak = isset($rakByNormCode[$subNorm]) ? $rakByNormCode[$subNorm] : null;

                if ($rak && $rak['total'] > 0) {
                    $m0 = $rak['jan']; $m1 = $rak['feb']; $m2 = $rak['mar']; $m3 = $rak['apr'];
                    $m4 = $rak['mei']; $m5 = $rak['jun']; $m6 = $rak['jul']; $m7 = $rak['ags'];
                    $m8 = $rak['sep']; $m9 = $rak['okt']; $m10 = $rak['nov']; $m11 = $rak['des'];
                    $totalRak = $rak['total'];
                } else {
                    $totalRak = (float)$h['total_belanja'];
                    $m0 = $m1 = $m2 = $m3 = $m4 = $m5 = $m6 = $m7 = $m8 = $m9 = $m10 = $m11 = 0;
                }

                $angData = [
                    'header_id' => $hId,
                    'kode_wilayah' => $h['kode_wilayah'] ?: $kode_wilayah,
                    'tahun' => $tahun,
                    'id_instansi' => $h['id_instansi'],
                    'kode_sub_kegiatan' => $subKode,
                    'jan' => $m0, 'feb' => $m1, 'mar' => $m2, 'apr' => $m3,
                    'mei' => $m4, 'jun' => $m5, 'jul' => $m6, 'ags' => $m7,
                    'sep' => $m8, 'okt' => $m9, 'nov' => $m10, 'des' => $m11,
                    'total_anggaran' => $totalRak,
                    'created_at' => $now,
                    'updated_at' => $now
                ];

                $this->db->insert('target_renaksi_anggaran_bulanan', $angData);
                $syncedCount++;
            }

            $this->db->trans_commit();

            // 3. Bangun ulang pohon Target Renaksi dari awal
            $freshTree = $this->_buildTargetRenaksiHierarchy($kode_wilayah, $tahun, $instansi_id);

            echo json_encode([
                'status' => 'success',
                'message' => "Data Target Renaksi berhasil direset & ditarik ulang dari Rankhir Renja & DPA ($syncedCount Sub Kegiatan)!",
                'data' => $freshTree
            ]);
        } catch (Exception $e) {
            $this->db->trans_rollback();
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    private function _buildTargetRenaksiHierarchy($KodeWilayah, $tahun, $filter_instansi = null) {
        $tahun = (int)($tahun ?: date('Y'));
        
        // 0. Pastikan snapshot Rankhir Renja tersedia untuk instansi dan tahun bersangkutan
        if (!empty($KodeWilayah) && !empty($filter_instansi)) {
            $this->ensureRancanganAkhirRenjaSnapshot($KodeWilayah, (int)$filter_instansi, $tahun);
        }

        // 1. Nomenklatur Map
        $nomen_rows = $this->db->select('Kode, Nomenklatur')->get('nomenklaturkabupaten')->result_array();
        $nomen_map = [];
        foreach ($nomen_rows as $n) {
            $nomen_map[trim($n['Kode'])] = $n['Nomenklatur'];
        }
        $normalizeCode = function($code) {
            if (empty($code)) return '';
            $parts = explode('.', trim((string)$code));
            $clean = [];
            foreach ($parts as $p) {
                $pTrim = trim($p);
                if (is_numeric($pTrim)) {
                    $clean[] = (string)(int)$pTrim;
                } else {
                    $clean[] = strtolower($pTrim);
                }
            }
            return implode('.', $clean);
        };

        // 2. Ambil data Belanja Sub Kegiatan Header & Rekening
        $this->db->select('*')->from('belanja_sub_kegiatan_header')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) {
            $this->db->where('kode_wilayah', $KodeWilayah);
        }
        if (!empty($tahun)) {
            $this->db->where('tahun', $tahun);
        }
        if (!empty($filter_instansi)) {
            $this->db->where('id_instansi', (int)$filter_instansi);
        }
        $dpaHeaders = $this->db
            ->order_by('kode_program', 'ASC')
            ->order_by('kode_kegiatan', 'ASC')
            ->order_by('kode_sub_kegiatan', 'ASC')
            ->get()
            ->result_array();
        
        $dpaHeaderMap = [];
        $dpaHeaderBySubkeg = [];
        $headerIds = [];
        foreach ($dpaHeaders as $dh) {
            $dhSk = trim($dh['kode_sub_kegiatan']);
            $dpaHeaderMap[(int)$dh['id']] = $dh;
            $dpaHeaderBySubkeg[$dhSk] = $dh;
            $dpaHeaderBySubkeg['norm_' . $normalizeCode($dhSk)] = $dh;
            $headerIds[] = (int)$dh['id'];
        }

        // Ambil total dari belanja_rekening jika ada
        $rekTotalMap = [];
        if (!empty($headerIds)) {
            $rekTotals = $this->db->select('header_id, SUM(total) as total_rek')
                ->where('deleted_at IS NULL')
                ->where_in('header_id', $headerIds)
                ->group_by('header_id')
                ->get('belanja_rekening')
                ->result_array();
            foreach ($rekTotals as $rt) {
                $rekTotalMap[(int)$rt['header_id']] = (float)$rt['total_rek'];
            }
        }

        // 3. Ambil data DPA: RAK Rincian
        $this->db->select('*')->from('dpa_rak_rincian')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) {
            $this->db->where('kode_wilayah', $KodeWilayah);
        }
        if (!empty($tahun)) {
            $this->db->where('tahun', $tahun);
        }
        if (!empty($filter_instansi)) {
            $this->db->group_start()
                ->where('id_instansi', (int)$filter_instansi)
                ->or_where('id_instansi IS NULL')
                ->or_where('id_instansi', 0)
            ->group_end();
        }
        $dpaRakRaw = $this->db->order_by('id', 'ASC')->get()->result_array();

        // Deduplikasi entri rincian RAK agar rincian yang sama tidak dijumlahkan berulang kali
        $uniqueRak = [];
        foreach ($dpaRakRaw as $dr) {
            $rKey = '';
            if (!empty($dr['rincian_id'])) {
                $rKey = 'r_' . $dr['rincian_id'];
            } else {
                $rKey = 'k_' . $normalizeCode($dr['kode_sub_kegiatan']) . '_' . trim($dr['kode_rekening'] ?? '') . '_' . trim($dr['uraian'] ?? '');
            }
            $uniqueRak[$rKey] = $dr;
        }

        $dpaRakMap = [];
        foreach ($uniqueRak as $dr) {
            $sk = trim($dr['kode_sub_kegiatan'] ?? '');
            if (empty($sk)) continue;

            $skNorm = 'norm_' . $normalizeCode($sk);

            if (!isset($dpaRakMap[$sk])) {
                $dpaRakMap[$sk] = [
                    'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                    'mei' => 0, 'jun' => 0, 'jul' => 0, 'agu' => 0,
                    'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
                    'total' => 0
                ];
            }
            if (!isset($dpaRakMap[$skNorm])) {
                $dpaRakMap[$skNorm] = [
                    'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                    'mei' => 0, 'jun' => 0, 'jul' => 0, 'agu' => 0,
                    'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
                    'total' => 0
                ];
            }

            $mJan = (float)($dr['jan'] ?? 0);
            $mFeb = (float)($dr['feb'] ?? 0);
            $mMar = (float)($dr['mar'] ?? 0);
            $mApr = (float)($dr['apr'] ?? 0);
            $mMei = (float)($dr['mei'] ?? 0);
            $mJun = (float)($dr['jun'] ?? 0);
            $mJul = (float)($dr['jul'] ?? 0);
            $mAgu = (float)($dr['ags'] ?? ($dr['agu'] ?? 0));
            $mSep = (float)($dr['sep'] ?? 0);
            $mOkt = (float)($dr['okt'] ?? 0);
            $mNov = (float)($dr['nov'] ?? 0);
            $mDes = (float)($dr['des'] ?? 0);
            $mTot = $mJan + $mFeb + $mMar + $mApr + $mMei + $mJun + $mJul + $mAgu + $mSep + $mOkt + $mNov + $mDes;
            $rowTot = (float)($dr['total_rak'] ?? 0) > 0 ? (float)$dr['total_rak'] : $mTot;

            $dpaRakMap[$sk]['jan'] += $mJan;
            $dpaRakMap[$sk]['feb'] += $mFeb;
            $dpaRakMap[$sk]['mar'] += $mMar;
            $dpaRakMap[$sk]['apr'] += $mApr;
            $dpaRakMap[$sk]['mei'] += $mMei;
            $dpaRakMap[$sk]['jun'] += $mJun;
            $dpaRakMap[$sk]['jul'] += $mJul;
            $dpaRakMap[$sk]['agu'] += $mAgu;
            $dpaRakMap[$sk]['sep'] += $mSep;
            $dpaRakMap[$sk]['okt'] += $mOkt;
            $dpaRakMap[$sk]['nov'] += $mNov;
            $dpaRakMap[$sk]['des'] += $mDes;
            $dpaRakMap[$sk]['total'] += $rowTot;

            $dpaRakMap[$skNorm]['jan'] += $mJan;
            $dpaRakMap[$skNorm]['feb'] += $mFeb;
            $dpaRakMap[$skNorm]['mar'] += $mMar;
            $dpaRakMap[$skNorm]['apr'] += $mApr;
            $dpaRakMap[$skNorm]['mei'] += $mMei;
            $dpaRakMap[$skNorm]['jun'] += $mJun;
            $dpaRakMap[$skNorm]['jul'] += $mJul;
            $dpaRakMap[$skNorm]['agu'] += $mAgu;
            $dpaRakMap[$skNorm]['sep'] += $mSep;
            $dpaRakMap[$skNorm]['okt'] += $mOkt;
            $dpaRakMap[$skNorm]['nov'] += $mNov;
            $dpaRakMap[$skNorm]['des'] += $mDes;
            $dpaRakMap[$skNorm]['total'] += $rowTot;

            // Alias keys
            $dpaRakMap['c_' . $sk] = $dpaRakMap[$sk];

            if (!empty($dr['header_id'])) {
                $hKey = 'h_' . $dr['header_id'];
                if (!isset($dpaRakMap[$hKey])) {
                    $dpaRakMap[$hKey] = [
                        'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                        'mei' => 0, 'jun' => 0, 'jul' => 0, 'agu' => 0,
                        'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
                        'total' => 0
                    ];
                }
                $dpaRakMap[$hKey]['jan'] += $mJan;
                $dpaRakMap[$hKey]['feb'] += $mFeb;
                $dpaRakMap[$hKey]['mar'] += $mMar;
                $dpaRakMap[$hKey]['apr'] += $mApr;
                $dpaRakMap[$hKey]['mei'] += $mMei;
                $dpaRakMap[$hKey]['jun'] += $mJun;
                $dpaRakMap[$hKey]['jul'] += $mJul;
                $dpaRakMap[$hKey]['agu'] += $mAgu;
                $dpaRakMap[$hKey]['sep'] += $mSep;
                $dpaRakMap[$hKey]['okt'] += $mOkt;
                $dpaRakMap[$hKey]['nov'] += $mNov;
                $dpaRakMap[$hKey]['des'] += $mDes;
                $dpaRakMap[$hKey]['total'] += $rowTot;
            }
        }

        // 4. Ambil Anggaran Bulanan Tersimpan di Target Renaksi
        $this->db->select('*')->from('target_renaksi_anggaran_bulanan')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('kode_wilayah', $KodeWilayah);
        if (!empty($tahun)) $this->db->where('tahun', $tahun);
        if (!empty($filter_instansi)) $this->db->where('id_instansi', (int)$filter_instansi);
        $anggaranSaved = $this->db->get()->result_array();

        $anggaranMap = [];
        foreach ($anggaranSaved as $ang) {
            $pagu = [
                'jan' => (float)$ang['jan'], 'feb' => (float)$ang['feb'], 'mar' => (float)$ang['mar'],
                'apr' => (float)$ang['apr'], 'mei' => (float)$ang['mei'], 'jun' => (float)$ang['jun'],
                'jul' => (float)$ang['jul'], 'agu' => (float)$ang['ags'], 'sep' => (float)$ang['sep'],
                'okt' => (float)$ang['okt'], 'nov' => (float)$ang['nov'], 'des' => (float)$ang['des']
            ];
            $val = [
                'pagu' => $pagu,
                'total' => (float)$ang['total_anggaran']
            ];
            if (!empty($ang['header_id'])) {
                $anggaranMap['h_' . $ang['header_id']] = $val;
            }
            if (!empty($ang['kode_sub_kegiatan'])) {
                $angSk = trim($ang['kode_sub_kegiatan']);
                $anggaranMap['c_' . $angSk] = $val;
                $anggaranMap['norm_' . $normalizeCode($angSk)] = $val;
            }
        }

        // 5. Ambil data indikator Sub Kegiatan tersimpan di Target Renaksi
        $this->db->select('*')->from('target_renaksi_indikator')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('kode_wilayah', $KodeWilayah);
        if (!empty($tahun)) $this->db->where('tahun', $tahun);
        if (!empty($filter_instansi)) $this->db->where('id_instansi', (int)$filter_instansi);
        $indikatorsSaved = $this->db
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get()
            ->result_array();

        $indikatorMap = [];
        foreach ($indikatorsSaved as $ind) {
            $item = [
                'id' => (string)$ind['id'],
                'nama' => $ind['uraian_indikator'],
                'satuan' => $ind['satuan'] ?: 'Dokumen',
                'targetTahunan' => $ind['target_tahunan'] !== null ? (float)$ind['target_tahunan'] : 1,
                'tw1' => $ind['tw1'] !== null ? (float)$ind['tw1'] : null,
                'tw2' => $ind['tw2'] !== null ? (float)$ind['tw2'] : null,
                'tw3' => $ind['tw3'] !== null ? (float)$ind['tw3'] : null,
                'tw4' => $ind['tw4'] !== null ? (float)$ind['tw4'] : null,
                'validitas' => $ind['validitas'] ?: 'Valid'
            ];
            if (!empty($ind['header_id'])) {
                $indikatorMap['h_' . $ind['header_id']][] = $item;
            }
            if (!empty($ind['entity_code'])) {
                $indikatorMap['c_' . trim($ind['entity_code'])][] = $item;
            }
        }

        // 6. Ambil Tahapan Proses Rencana Aksi tersimpan di Target Renaksi
        $this->db->select('*')->from('target_renaksi_tahapan_proses')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('kode_wilayah', $KodeWilayah);
        if (!empty($tahun)) $this->db->where('tahun', $tahun);
        if (!empty($filter_instansi)) $this->db->where('id_instansi', (int)$filter_instansi);
        $tahapanSaved = $this->db
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get()
            ->result_array();

        $tahapanMap = [];
        foreach ($tahapanSaved as $tp) {
            $item = [
                'id' => (string)$tp['id'],
                'uraian' => $tp['uraian'],
                'nilai' => $tp['target_output_nilai'] !== null ? (float)$tp['target_output_nilai'] : 1,
                'satuan' => $tp['target_output_satuan'] ?: 'berkas',
                'bobot' => $tp['bobot_kinerja_output'] !== null ? (float)$tp['bobot_kinerja_output'] : 0,
                'bulan' => $tp['rencana_bulan'] ?: 'Januari',
                'bobotSubKeg' => $tp['bobot_kinerja_sub_kegiatan'] !== null ? (float)$tp['bobot_kinerja_sub_kegiatan'] : 0,
                'keterangan' => $tp['keterangan'] ?: ''
            ];
            if (!empty($tp['header_id'])) {
                $tahapanMap['h_' . $tp['header_id']][] = $item;
            }
            if (!empty($tp['kode_sub_kegiatan'])) {
                $tahapanMap['c_' . trim($tp['kode_sub_kegiatan'])] = $item;
            }
        }

        // 7. Ambil Target Hierarki tersimpan (Tujuan, Sasaran Strategis, Program, Kegiatan)
        $this->db->select('*')->from('target_renaksi_hierarchy')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('kode_wilayah', $KodeWilayah);
        if (!empty($tahun)) $this->db->where('tahun', $tahun);
        if (!empty($filter_instansi)) $this->db->where('id_instansi', (int)$filter_instansi);
        $hierSaved = $this->db
            ->order_by('urutan', 'ASC')
            ->get()
            ->result_array();

        $hierMap = [];
        foreach ($hierSaved as $hRow) {
            $k = $hRow['level_type'] . '_' . trim($hRow['entity_code']);
            $hierMap[$k][] = [
                'id' => (string)$hRow['id'],
                'nama' => $hRow['indikator_nama'],
                'satuan' => $hRow['satuan'] ?: '%',
                'targetTahunan' => $hRow['target_tahunan'] !== null ? (float)$hRow['target_tahunan'] : 100,
                'tw1' => $hRow['tw1'] !== null ? (float)$hRow['tw1'] : null,
                'tw2' => $hRow['tw2'] !== null ? (float)$hRow['tw2'] : null,
                'tw3' => $hRow['tw3'] !== null ? (float)$hRow['tw3'] : null,
                'tw4' => $hRow['tw4'] !== null ? (float)$hRow['tw4'] : null
            ];
        }

        // 8. Ambil Snapshots Rankhir Renja Kegiatan & Sub Kegiatan
        $kegSnapshotMap = [];
        if (!empty($filter_instansi)) {
            $this->db->select('*')->from('rancangan_akhir_renja_kegiatan_data')->where('deleted_at IS NULL')
                ->where('kode_wilayah', $KodeWilayah)
                ->where('id_instansi', (int)$filter_instansi)
                ->where('tahun', $tahun);
            $kegSnaps = $this->db->get()->result_array();
            foreach ($kegSnaps as $ks) {
                $kegSnapshotMap[$ks['kegiatan_id']] = $ks;
            }
        }

        $subSnapshotMap = [];
        if (!empty($filter_instansi)) {
            $this->db->select('*')->from('rancangan_akhir_renja_sub_kegiatan_data')->where('deleted_at IS NULL')
                ->where('kode_wilayah', $KodeWilayah)
                ->where('id_instansi', (int)$filter_instansi)
                ->where('tahun', $tahun);
            $subSnaps = $this->db->get()->result_array();
            foreach ($subSnaps as $ss) {
                $subSnapshotMap[$ss['sub_kegiatan_id']] = $ss;
            }
        }

        // 9. Ambil Struktur Rankhir Renja (Tujuan -> Sasaran -> Program -> Kegiatan -> Sub Kegiatan)
        $this->db->select('*')->from('renstra_tujuan')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) $this->db->where('kode_wilayah', $KodeWilayah);
        if (!empty($filter_instansi)) $this->db->where('id_instansi', (int)$filter_instansi);
        $tujuanRows = $this->db->order_by('id', 'ASC')->get()->result_array();

        $processedSubKodes = [];
        $tujuanList = [];

        foreach ($tujuanRows as $t) {
            $tId = (int)$t['id'];
            $tKode = 'T_' . $tId;
            $tNama = $t['uraian'] ?: ('Tujuan ' . $tId);

            // Indikator Tujuan
            $tInds = [];
            if (isset($hierMap['tujuan_' . $tKode])) {
                $tInds = $hierMap['tujuan_' . $tKode];
            } else if (isset($hierMap['tujuan_t_' . $tId])) {
                $tInds = $hierMap['tujuan_t_' . $tId];
            } else {
                $dbTInds = $this->db->where('tujuan_id', $tId)->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_tujuan_indikator')->result_array();
                foreach ($dbTInds as $ti) {
                    $tgt = $ti['target_' . $tahun] ?? ($ti['target_2026'] ?? 100);
                    $tgtClean = str_replace(',', '.', trim((string)$tgt));
                    $tgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                    if ($tgtVal <= 0) $tgtVal = 100;
                    $tInds[] = [
                        'id' => 'ind_t_' . $ti['id'],
                        'nama' => $ti['indikator'] ?: '-',
                        'satuan' => $ti['satuan'] ?: '%',
                        'targetTahunan' => $tgtVal,
                        'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                    ];
                }
                if (empty($tInds) && !empty($t['indikator'])) {
                    $tgt = $t['target_' . $tahun] ?? ($t['target_2026'] ?? 100);
                    $tgtClean = str_replace(',', '.', trim((string)$tgt));
                    $tgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                    if ($tgtVal <= 0) $tgtVal = 100;
                    $tInds[] = [
                        'id' => 'ind_t_def_' . $tId,
                        'nama' => $t['indikator'],
                        'satuan' => $t['satuan'] ?: '%',
                        'targetTahunan' => $tgtVal,
                        'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                    ];
                }
                if (empty($tInds)) {
                    $tInds[] = [
                        'id' => 'ind_t_def_' . $tId,
                        'nama' => 'Persentase pencapaian sasaran tujuan ' . $tNama,
                        'satuan' => '%',
                        'targetTahunan' => 100,
                        'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                    ];
                }
            }

            // Sasaran Strategis
            $ssRows = $this->db->where('tujuan_id', $tId)->where('deleted_at IS NULL')->order_by('id', 'ASC')->get('renstra_sasaran')->result_array();
            $ssList = [];

            foreach ($ssRows as $s) {
                $ssId = (int)$s['id'];
                $ssKode = 'SS_' . $ssId;
                $ssNama = $s['uraian'] ?: ('Sasaran Strategis ' . $ssId);

                // Indikator Sasaran Strategis
                $ssInds = [];
                if (isset($hierMap['sasaran_strategis_' . $ssKode])) {
                    $ssInds = $hierMap['sasaran_strategis_' . $ssKode];
                } else if (isset($hierMap['sasaran_strategis_ss_' . $ssId])) {
                    $ssInds = $hierMap['sasaran_strategis_ss_' . $ssId];
                } else {
                    $dbSSInds = $this->db->where('sasaran_id', $ssId)->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_sasaran_indikator')->result_array();
                    foreach ($dbSSInds as $si) {
                        $tgt = $si['target_' . $tahun] ?? ($si['target_2026'] ?? 100);
                        $tgtClean = str_replace(',', '.', trim((string)$tgt));
                        $tgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                        if ($tgtVal <= 0) $tgtVal = 100;
                        $ssInds[] = [
                            'id' => 'ind_ss_' . $si['id'],
                            'nama' => $si['indikator'] ?: '-',
                            'satuan' => $si['satuan'] ?: '%',
                            'targetTahunan' => $tgtVal,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                        ];
                    }
                    if (empty($ssInds) && !empty($s['indikator'])) {
                        $tgt = $s['target_' . $tahun] ?? ($s['target_2026'] ?? 100);
                        $tgtClean = str_replace(',', '.', trim((string)$tgt));
                        $tgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                        if ($tgtVal <= 0) $tgtVal = 100;
                        $ssInds[] = [
                            'id' => 'ind_ss_def_' . $ssId,
                            'nama' => $s['indikator'],
                            'satuan' => $s['satuan'] ?: '%',
                            'targetTahunan' => $tgtVal,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                        ];
                    }
                    if (empty($ssInds)) {
                        $ssInds[] = [
                            'id' => 'ind_ss_def_' . $ssId,
                            'nama' => 'Persentase ketercapaian target ' . $ssNama,
                            'satuan' => '%',
                            'targetTahunan' => 100,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                        ];
                    }
                }

                // Sasaran Program
                $progRows = $this->db->where('sasaran_id', $ssId)->where('deleted_at IS NULL')->order_by('id', 'ASC')->get('renstra_program')->result_array();
                $spList = [];

                foreach ($progRows as $p) {
                    $pId = (int)$p['id'];
                    $pKode = trim($p['kode_program'] ?? '');
                    $pNamaNomen = isset($nomen_map[$pKode]) ? $nomen_map[$pKode] : ('PROGRAM ' . $pKode);
                    $pNama = !empty($p['nama_program']) ? $p['nama_program'] : $pNamaNomen;

                    // Indikator Program
                    $spInds = [];
                    if (isset($hierMap['program_' . $pKode])) {
                        $spInds = $hierMap['program_' . $pKode];
                    } else if (isset($hierMap['program_sp_' . $pId])) {
                        $spInds = $hierMap['program_sp_' . $pId];
                    } else {
                        $outRow = $this->db->where('program_id', $pId)->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_program_outcome')->row_array();
                        $indRow = $outRow ? $this->db->where('outcome_id', $outRow['id'])->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_program_indikator')->row_array() : null;
                        
                        $pIndText = $indRow['indikator'] ?? ($p['indikator'] ?? ($outRow['outcome_text'] ?? ('Indikator ' . $pNamaNomen)));
                        $pSatuan = $indRow['satuan'] ?? ($p['satuan'] ?? '%');
                        $pTgt = $indRow['target_' . $tahun] ?? ($p['target_' . $tahun] ?? 100);
                        $tgtClean = str_replace(',', '.', trim((string)$pTgt));
                        $pTgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                        if ($pTgtVal <= 0) $pTgtVal = 100;

                        $spInds[] = [
                            'id' => 'ind_sp_' . ($indRow['id'] ?? $pId),
                            'nama' => $pIndText,
                            'satuan' => $pSatuan ?: '%',
                            'targetTahunan' => $pTgtVal,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                        ];
                    }

                    // Sasaran Kegiatan
                    $kegRows = $this->db->where('program_id', $pId)->where('deleted_at IS NULL')->order_by('id', 'ASC')->get('renstra_kegiatan')->result_array();
                    $skList = [];
                    $progTotalAnggaran = 0;

                    foreach ($kegRows as $k) {
                        $kId = (int)$k['id'];
                        $kKode = trim($k['kode_kegiatan'] ?? ($k['kode_nomenklatur'] ?? ''));
                        $kNamaNomen = isset($nomen_map[$kKode]) ? $nomen_map[$kKode] : (!empty($k['nama']) ? $k['nama'] : ('KEGIATAN ' . $kKode));
                        $kNama = !empty($k['nama']) ? $k['nama'] : (!empty($k['nama_kegiatan']) ? $k['nama_kegiatan'] : $kNamaNomen);
                        $kPerihal = !empty($k['sasaran']) ? $k['sasaran'] : $kNama;

                        // Rankhir Renja Snapshot Kegiatan
                        $kSnap = isset($kegSnapshotMap[$kId]) ? $kegSnapshotMap[$kId] : null;
                        $kindRow = $this->db->where('kegiatan_id', $kId)->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_kegiatan_indikator')->row_array();

                        // Indikator Kegiatan
                        $skInds = [];
                        if (isset($hierMap['kegiatan_' . $kKode])) {
                            $skInds = $hierMap['kegiatan_' . $kKode];
                        } else if (isset($hierMap['kegiatan_sk_' . $kId])) {
                            $skInds = $hierMap['kegiatan_sk_' . $kId];
                        } else {
                            $kIndText = $kSnap['indikator'] ?? ($kindRow['indikator'] ?? ($k['indikator'] ?? ('Indikator ' . $kNamaNomen)));
                            $kSatuan = $kSnap['satuan'] ?? ($kindRow['satuan'] ?? ($k['satuan'] ?? '%'));
                            $kTgt = $kSnap['target'] ?? ($kindRow['target_' . $tahun] ?? ($k['target_' . $tahun] ?? 100));
                            $tgtClean = str_replace(',', '.', trim((string)$kTgt));
                            $kTgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                            if ($kTgtVal <= 0) $kTgtVal = 100;

                            $skInds[] = [
                                'id' => 'ind_sk_' . ($kindRow['id'] ?? $kId),
                                'nama' => $kIndText,
                                'satuan' => $kSatuan ?: '%',
                                'targetTahunan' => $kTgtVal,
                                'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                            ];
                        }

                        // Sasaran Sub Kegiatan
                        $subRows = $this->db->where('kegiatan_id', $kId)->where('deleted_at IS NULL')->order_by('id', 'ASC')->get('renstra_sub_kegiatan')->result_array();
                        $subList = [];
                        $kegTotalAnggaran = 0;

                        foreach ($subRows as $skItem) {
                            $skId = (int)$skItem['id'];
                            $subKode = trim($skItem['kode_sub_kegiatan'] ?? ($skItem['kode_nomenklatur'] ?? ''));
                            $subNamaNomen = isset($nomen_map[$subKode]) ? $nomen_map[$subKode] : (!empty($skItem['nama']) ? $skItem['nama'] : ('Sub Kegiatan ' . $subKode));
                            $subNama = !empty($skItem['nama']) ? $skItem['nama'] : (!empty($skItem['nama_sub_kegiatan']) ? $skItem['nama_sub_kegiatan'] : $subNamaNomen);
                            $subPerihal = !empty($skItem['sasaran']) ? $skItem['sasaran'] : $subNama;

                            $processedSubKodes[$subKode] = true;

                            // Snapshot Rankhir Renja Sub Kegiatan
                            $subSnap = isset($subSnapshotMap[$skId]) ? $subSnapshotMap[$skId] : null;
                            $skindRow = $this->db->where('sub_kegiatan_id', $skId)->where('deleted_at IS NULL')->order_by('urutan', 'ASC')->get('renstra_sub_kegiatan_indikator')->row_array();

                            // Cari Data DPA Header
                            $subNorm = 'norm_' . $normalizeCode($subKode);
                            $dpaH = isset($dpaHeaderBySubkeg[$subKode]) ? $dpaHeaderBySubkeg[$subKode] : (isset($dpaHeaderBySubkeg[$subNorm]) ? $dpaHeaderBySubkeg[$subNorm] : null);
                            $hId = $dpaH ? (int)$dpaH['id'] : $skId;

                            // Indikator Sub Kegiatan
                            $inds = [];
                            if (isset($indikatorMap['h_' . $hId])) {
                                $inds = $indikatorMap['h_' . $hId];
                            } else if (isset($indikatorMap['c_' . $subKode])) {
                                $inds = $indikatorMap['c_' . $subKode];
                            } else {
                                $subIndText = $subSnap['indikator'] ?? ($skindRow['indikator'] ?? ($skItem['indikator'] ?? ('Indikator ' . $subNama)));
                                $subSatuan = $subSnap['satuan'] ?? ($skindRow['satuan'] ?? ($skItem['satuan'] ?? '%'));
                                $subTgt = $subSnap['target'] ?? ($skindRow['target_' . $tahun] ?? ($skItem['target_' . $tahun] ?? 100));
                                $tgtClean = str_replace(',', '.', trim((string)$subTgt));
                                $subTgtVal = is_numeric($tgtClean) ? (float)$tgtClean : (float)preg_replace('/[^0-9.]/', '', $tgtClean);
                                if ($subTgtVal <= 0) $subTgtVal = 100;

                                $inds = [
                                    [
                                        'id' => 'ind_sub_' . ($skindRow['id'] ?? $skId),
                                        'nama' => $subIndText,
                                        'satuan' => $subSatuan ?: '%',
                                        'targetTahunan' => $subTgtVal,
                                        'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null,
                                        'validitas' => 'Valid'
                                    ]
                                ];
                            }

                            // Tahapan Proses
                            $tps = isset($tahapanMap['h_' . $hId]) ? $tahapanMap['h_' . $hId] : (isset($tahapanMap['c_' . $subKode]) ? $tahapanMap['c_' . $subKode] : []);

                            // Anggaran Menarik dari DPA Belanja Sub Kegiatan / RAK
                            $dpaRakItem = null;
                            if (!empty($hId) && isset($dpaRakMap['h_' . $hId])) {
                                $dpaRakItem = $dpaRakMap['h_' . $hId];
                            } else if (isset($dpaRakMap[$subKode])) {
                                $dpaRakItem = $dpaRakMap[$subKode];
                            } else if (isset($dpaRakMap['c_' . $subKode])) {
                                $dpaRakItem = $dpaRakMap['c_' . $subKode];
                            } else if (isset($dpaRakMap[$subNorm])) {
                                $dpaRakItem = $dpaRakMap[$subNorm];
                            }

                            $angItem = null;
                            if (!empty($hId) && isset($anggaranMap['h_' . $hId])) {
                                $angItem = $anggaranMap['h_' . $hId];
                            } else if (isset($anggaranMap['c_' . $subKode])) {
                                $angItem = $anggaranMap['c_' . $subKode];
                            } else if (isset($anggaranMap[$subNorm])) {
                                $angItem = $anggaranMap[$subNorm];
                            }

                            $totalBelanjaSub = 0;
                            if ($dpaRakItem && $dpaRakItem['total'] > 0) {
                                $totalBelanjaSub = (float)$dpaRakItem['total'];
                            }
                            if ($dpaH) {
                                $dpaTot = (float)$dpaH['total_belanja'];
                                if ($dpaTot <= 0 && isset($rekTotalMap[(int)$dpaH['id']]) && $rekTotalMap[(int)$dpaH['id']] > 0) {
                                    $dpaTot = $rekTotalMap[(int)$dpaH['id']];
                                }
                                if ($dpaTot > 0) {
                                    $totalBelanjaSub = $dpaTot;
                                }
                            }

                            $pagu = [
                                'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                                'mei' => 0, 'jun' => 0, 'jul' => 0, 'agu' => 0,
                                'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0
                            ];
                            $totalAnggaran = $totalBelanjaSub;

                            if ($angItem) {
                                $pagu = $angItem['pagu'];
                                if ($totalAnggaran <= 0) $totalAnggaran = $angItem['total'];
                            } else if ($dpaRakItem) {
                                $pagu = [
                                    'jan' => (float)$dpaRakItem['jan'], 'feb' => (float)$dpaRakItem['feb'], 'mar' => (float)$dpaRakItem['mar'],
                                    'apr' => (float)$dpaRakItem['apr'], 'mei' => (float)$dpaRakItem['mei'], 'jun' => (float)$dpaRakItem['jun'],
                                    'jul' => (float)$dpaRakItem['jul'], 'agu' => (float)$dpaRakItem['agu'], 'sep' => (float)$dpaRakItem['sep'],
                                    'okt' => (float)$dpaRakItem['okt'], 'nov' => (float)$dpaRakItem['nov'], 'des' => (float)$dpaRakItem['des']
                                ];
                                if ($totalAnggaran <= 0) $totalAnggaran = $dpaRakItem['total'];
                            } else if ($totalAnggaran > 0) {
                                $mShare = $totalAnggaran / 12;
                                $pagu = [
                                    'jan' => $mShare, 'feb' => $mShare, 'mar' => $mShare, 'apr' => $mShare,
                                    'mei' => $mShare, 'jun' => $mShare, 'jul' => $mShare, 'agu' => $mShare,
                                    'sep' => $mShare, 'okt' => $mShare, 'nov' => $mShare, 'des' => $mShare
                                ];
                            } else if ($totalAnggaran <= 0 && $subSnap && (float)$subSnap['anggaran'] > 0) {
                                $totalAnggaran = (float)$subSnap['anggaran'];
                                $mShare = $totalAnggaran / 12;
                                $pagu = [
                                    'jan' => $mShare, 'feb' => $mShare, 'mar' => $mShare, 'apr' => $mShare,
                                    'mei' => $mShare, 'jun' => $mShare, 'jul' => $mShare, 'agu' => $mShare,
                                    'sep' => $mShare, 'okt' => $mShare, 'nov' => $mShare, 'des' => $mShare
                                ];
                            }

                            $kegTotalAnggaran += $totalAnggaran;

                            $subList[] = [
                                'id' => (string)$hId,
                                'headerId' => $hId,
                                'kode' => $subKode,
                                'nama' => $subNama,
                                'nomenklatur' => $subNamaNomen,
                                'perihal' => $subPerihal,
                                'perangkatDaerah' => $dpaH['nama_perangkat_daerah'] ?? '',
                                'subUnit' => $dpaH['nama_sub_unit'] ?? '',
                                'bidangUrusan' => $dpaH['nama_bidang_urusan'] ?? '',
                                'programNama' => $dpaH['nama_program'] ?? $pNamaNomen,
                                'kegiatanNama' => $dpaH['nama_kegiatan'] ?? $kNamaNomen,
                                'indikators' => $inds,
                                'paguBulanan' => $pagu,
                                'anggaran' => $totalAnggaran,
                                'tahapanProses' => $tps
                            ];
                        }

                        $progTotalAnggaran += $kegTotalAnggaran;

                        $skList[] = [
                            'id' => 'sk_' . ($kKode ? str_replace('.', '_', $kKode) : $kId),
                            'kode' => $kKode,
                            'nama' => $kNama,
                            'nomenklatur' => $kNamaNomen,
                            'perihal' => $kPerihal,
                            'indikators' => $skInds,
                            'anggaran' => $kegTotalAnggaran,
                            'sasaranSubKegiatanList' => $subList
                        ];
                    }

                    $spList[] = [
                        'id' => 'sp_' . ($pKode ? str_replace('.', '_', $pKode) : $pId),
                        'kode' => $pKode,
                        'nama' => $pNama,
                        'nomenklatur' => $pNamaNomen,
                        'indikators' => $spInds,
                        'anggaran' => $progTotalAnggaran,
                        'sasaranKegiatanList' => $skList
                    ];
                }

                $ssList[] = [
                    'id' => 'ss_' . $ssId,
                    'kode' => $ssKode,
                    'nama' => $ssNama,
                    'indikators' => $ssInds,
                    'sasaranProgramList' => $spList
                ];
            }

            $tujuanList[] = [
                'id' => 't_' . $tId,
                'kode' => $tKode,
                'nama' => $tNama,
                'indikators' => $tInds,
                'sasaranStrategisList' => $ssList
            ];
        }

        // 10. Jika belum ada pohon Renstra sama sekali untuk instansi ini, fallback dari DPA
        if (empty($tujuanList)) {
            $unmappedProgGroups = [];
            foreach ($dpaHeaders as $h) {
                $hId = (int)$h['id'];
                $subKode = trim($h['kode_sub_kegiatan']);
                $kegKode = trim($h['kode_kegiatan'] ?: substr($subKode, 0, 13));
                $progKode = trim($h['kode_program'] ?: substr($kegKode, 0, 7));

                $inds = isset($indikatorMap['h_' . $hId]) ? $indikatorMap['h_' . $hId] : (isset($indikatorMap['c_' . $subKode]) ? $indikatorMap['c_' . $subKode] : []);
                if (empty($inds)) {
                    $inds = [
                        [
                            'id' => 'ind_def_' . $hId,
                            'nama' => 'Jumlah output sub kegiatan ' . ($h['nama_sub_kegiatan'] ?: $subKode),
                            'satuan' => '%',
                            'targetTahunan' => 100,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null,
                            'validitas' => 'Valid'
                        ]
                    ];
                }

                $tps = isset($tahapanMap['h_' . $hId]) ? $tahapanMap['h_' . $hId] : (isset($tahapanMap['c_' . $subKode]) ? $tahapanMap['c_' . $subKode] : []);

                $totalBelanjaSub = (float)$h['total_belanja'];
                if ($totalBelanjaSub <= 0 && isset($rekTotalMap[$hId]) && $rekTotalMap[$hId] > 0) {
                    $totalBelanjaSub = $rekTotalMap[$hId];
                }

                $pagu = [
                    'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                    'mei' => 0, 'jun' => 0, 'jul' => 0, 'agu' => 0,
                    'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0
                ];
                $totalAnggaran = $totalBelanjaSub;

                if (isset($anggaranMap['h_' . $hId])) {
                    $pagu = $anggaranMap['h_' . $hId]['pagu'];
                    if ($totalAnggaran <= 0) $totalAnggaran = $anggaranMap['h_' . $hId]['total'];
                } else if (isset($anggaranMap['c_' . $subKode])) {
                    $pagu = $anggaranMap['c_' . $subKode]['pagu'];
                    if ($totalAnggaran <= 0) $totalAnggaran = $anggaranMap['c_' . $subKode]['total'];
                } else if (isset($dpaRakMap[$subKode])) {
                    $pagu = $dpaRakMap[$subKode];
                    if ($totalAnggaran <= 0) $totalAnggaran = $dpaRakMap[$subKode]['total'];
                }

                $subItem = [
                    'id' => (string)$hId,
                    'headerId' => $hId,
                    'kode' => $subKode,
                    'nama' => $h['nama_sub_kegiatan'] ?: ($nomen_map[$subKode] ?? ('Sub Kegiatan ' . $subKode)),
                    'nomenklatur' => $nomen_map[$subKode] ?? ($h['nama_sub_kegiatan'] ?: ('Sub Kegiatan ' . $subKode)),
                    'perangkatDaerah' => $h['nama_perangkat_daerah'] ?: '',
                    'subUnit' => $h['nama_sub_unit'] ?: '',
                    'bidangUrusan' => $h['nama_bidang_urusan'] ?: '',
                    'programNama' => $h['nama_program'] ?: ($nomen_map[$progKode] ?? ''),
                    'kegiatanNama' => $h['nama_kegiatan'] ?: ($nomen_map[$kegKode] ?? ''),
                    'indikators' => $inds,
                    'paguBulanan' => $pagu,
                    'anggaran' => $totalAnggaran,
                    'tahapanProses' => $tps
                ];

                $unmappedProgGroups[$progKode][$kegKode][] = $subItem;
            }

            $unmappedSpList = [];
            foreach ($unmappedProgGroups as $pKode => $kegGroup) {
                $pName = isset($nomen_map[$pKode]) ? $nomen_map[$pKode] : ('PROGRAM ' . $pKode);
                $unmappedSkList = [];
                $progTotalAng = 0;

                foreach ($kegGroup as $kKode => $subList) {
                    $kName = isset($nomen_map[$kKode]) ? $nomen_map[$kKode] : ('KEGIATAN ' . $kKode);
                    $kegTotalAng = 0;
                    foreach ($subList as $s) {
                        $kegTotalAng += (float)$s['anggaran'];
                        $pName = $s['programNama'] ?: $pName;
                        $kName = $s['kegiatanNama'] ?: $kName;
                    }
                    $progTotalAng += $kegTotalAng;

                    $kInds = isset($hierMap['kegiatan_' . $kKode]) ? $hierMap['kegiatan_' . $kKode] : [
                        [
                            'id' => 'ind_sk_' . str_replace('.', '_', $kKode),
                            'nama' => 'Persentase ketercapaian target output ' . $kName,
                            'satuan' => '%',
                            'targetTahunan' => 100,
                            'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                        ]
                    ];

                    $unmappedSkList[] = [
                        'id' => 'sk_' . str_replace('.', '_', $kKode),
                        'kode' => $kKode,
                        'nama' => $kName,
                        'nomenklatur' => $kName,
                        'indikators' => $kInds,
                        'anggaran' => $kegTotalAng,
                        'sasaranSubKegiatanList' => $subList
                    ];
                }

                $pInds = isset($hierMap['program_' . $pKode]) ? $hierMap['program_' . $pKode] : [
                    [
                        'id' => 'ind_sp_' . str_replace('.', '_', $pKode),
                        'nama' => 'Persentase pemenuhan standar kualitas proses ' . $pName,
                        'satuan' => '%',
                        'targetTahunan' => 100,
                        'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null
                    ]
                ];

                $unmappedSpList[] = [
                    'id' => 'sp_' . str_replace('.', '_', $pKode),
                    'kode' => $pKode,
                    'nama' => $pName,
                    'nomenklatur' => $pName,
                    'indikators' => $pInds,
                    'anggaran' => $progTotalAng,
                    'sasaranKegiatanList' => $unmappedSkList
                ];
            }

            $tujuanList[] = [
                'id' => 't_dpa_1',
                'kode' => 'T_1',
                'nama' => 'Tujuan Perangkat Daerah',
                'indikators' => [
                    ['id' => 'ind_t_dpa_1', 'nama' => 'Persentase Ketercapaian Tujuan PD', 'satuan' => '%', 'targetTahunan' => 100, 'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null]
                ],
                'sasaranStrategisList' => [
                    [
                        'id' => 'ss_dpa_1',
                        'kode' => 'SS_1',
                        'nama' => 'Sasaran Perangkat Daerah',
                        'indikators' => [
                            ['id' => 'ind_ss_dpa_1', 'nama' => 'Indeks Kepuasan Layanan PD', 'satuan' => 'Nilai', 'targetTahunan' => 100, 'tw1' => null, 'tw2' => null, 'tw3' => null, 'tw4' => null]
                        ],
                        'sasaranProgramList' => $unmappedSpList
                    ]
                ]
            ];
        }

        return [
            'tujuanList' => $tujuanList
        ];
    }

    // ================================================================
    // REALISASI RENAKSI (REALISASI KINERJA & ANGGARAN)
    // ================================================================

    public function RealisasiRenaksi() {
        $Header['Halaman'] = 'Realisasi Renaksi';
        
        $KodeWilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        $is_role_4 = $this->is_role_4();
        $tahun = $this->input->get('tahun', TRUE);
        $filter_instansi = $this->input->get('instansi_id', TRUE);
        $bulanIdx = $this->input->get('bulan', TRUE) !== null ? (int)$this->input->get('bulan', TRUE) : 0;
        
        if ($is_role_4 && $instansi_id) {
            $filter_instansi = $instansi_id;
        }

        // Batasi rentang bulan 0-11
        if ($bulanIdx < 0) $bulanIdx = 0;
        if ($bulanIdx > 11) $bulanIdx = 11;

        // Data Provinsi untuk filter
        $Data['Provinsi'] = $this->db
            ->where("Kode LIKE '__'")
            ->order_by('Nama')
            ->get('kodewilayah')
            ->result_array();
        
        $is_logged_in = $this->is_logged_in();
        $Data['IsLoggedIn'] = $is_logged_in;
        $Data['KodeWilayah'] = $KodeWilayah;
        $Data['NamaWilayah'] = '';
        $Data['IsRole4'] = $is_role_4;
        $Data['IsDaerah'] = $is_logged_in && !$is_role_4;
        $Data['InstansiId'] = $instansi_id;
        $Data['ControllerName'] = 'Instansi';
        
        if (!empty($KodeWilayah)) {
            $wilayah = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            $Data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
        }
        
        // List Instansi
        $Data['ListInstansi'] = [];
        if (!empty($KodeWilayah)) {
            $provKode = substr($KodeWilayah, 0, 2);
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where("(kodewilayah = " . $this->db->escape($KodeWilayah) . " OR kodewilayah = " . $this->db->escape($provKode) . ")")
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        } else {
            $Data['ListInstansi'] = $this->db
                ->select('id, nama')
                ->from('akun_instansi')
                ->where('deleted_at IS NULL')
                ->order_by('nama', 'ASC')
                ->get()
                ->result_array();
        }
        
        // List Tahun
        $dbYears = $this->db->select('DISTINCT(tahun) as thn')
            ->where('deleted_at IS NULL')
            ->order_by('tahun', 'DESC')
            ->get('belanja_sub_kegiatan_header')
            ->result_array();
        
        $listTahun = [];
        if (!empty($dbYears)) {
            foreach ($dbYears as $dy) {
                if (!empty($dy['thn'])) {
                    $listTahun[] = (int)$dy['thn'];
                }
            }
        }
        $currentY = (int)date('Y');
        for ($y = $currentY + 1; $y >= $currentY - 5; $y--) {
            if (!in_array($y, $listTahun)) {
                $listTahun[] = $y;
            }
        }
        rsort($listTahun);
        $Data['ListTahun'] = $listTahun;
        
        if (empty($tahun)) {
            if (!empty($dbYears) && !empty($dbYears[0]['thn'])) {
                $tahun = $dbYears[0]['thn'];
            } else {
                $tahun = date('Y');
            }
        }
        $Data['TahunAktif'] = $tahun;
        $Data['FilterInstansi'] = $filter_instansi;
        $Data['BulanAktif'] = $bulanIdx;

        // Ambil Data Hierarki Realisasi Renaksi
        if (!$is_logged_in && empty($KodeWilayah)) {
            $Data['RealisasiTree'] = [];
        } else {
            $Data['RealisasiTree'] = $this->_buildRealisasiRenaksiHierarchy($KodeWilayah, $tahun, $filter_instansi, $bulanIdx);
        }
        
        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/RealisasiRenaksi', $Data);
    }

    public function GetRealisasiRenaksiData() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $KodeWilayah = $this->get_kode_wilayah();
        $is_role_4 = $this->is_role_4();
        $instansi_id = $this->get_instansi_id();
        $tahun = $this->input->post('tahun', TRUE) ?: date('Y');
        $filter_instansi = $this->input->post('instansi', TRUE);
        $bulanIdx = $this->input->post('bulan', TRUE) !== null ? (int)$this->input->post('bulan', TRUE) : 0;

        if ($is_role_4 && $instansi_id) {
            $filter_instansi = $instansi_id;
        }

        $tree = $this->_buildRealisasiRenaksiHierarchy($KodeWilayah, $tahun, $filter_instansi, $bulanIdx);
        echo json_encode(['status' => 'success', 'data' => $tree]);
    }

    public function GetSubKegiatanRealisasiDetail() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $header_id = (int)$this->input->post('header_id', TRUE);
        $kode_sub_kegiatan = trim($this->input->post('kode_sub_kegiatan', TRUE));
        $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
        $bulanIdx = $this->input->post('bulan', TRUE) !== null ? (int)$this->input->post('bulan', TRUE) : 0;

        $this->db->where('deleted_at IS NULL');
        if ($header_id > 0) {
            $this->db->where('id', $header_id);
        } else if (!empty($kode_sub_kegiatan)) {
            $this->db->where('kode_sub_kegiatan', $kode_sub_kegiatan)->where('tahun', $tahun);
        }
        $header = $this->db->get('belanja_sub_kegiatan_header')->row_array();

        if (!$header) {
            echo json_encode(['status' => 'error', 'message' => 'Data Sub Kegiatan tidak ditemukan.']);
            return;
        }

        $hId = (int)$header['id'];
        $subKode = $header['kode_sub_kegiatan'];
        $thn = (int)$header['tahun'];

        // 1. Target Anggaran Bulanan dari Target Renaksi
        $targetAng = null;
        if ($hId > 0) {
            $targetAng = $this->db->where('deleted_at IS NULL')
                ->where('header_id', $hId)
                ->where('tahun', $thn)
                ->get('target_renaksi_anggaran_bulanan')
                ->row_array();
        }
        if (!$targetAng && !empty($subKode)) {
            $this->db->where('deleted_at IS NULL')
                ->where('kode_sub_kegiatan', $subKode)
                ->where('tahun', $thn);
            if (!empty($header['id_instansi'])) {
                $this->db->where('id_instansi', (int)$header['id_instansi']);
            }
            $targetAng = $this->db->get('target_renaksi_anggaran_bulanan')->row_array();
        }

        if (!$targetAng) {
            // Ambil dari DPA RAK rincian jika belum tersimpan di target_renaksi_anggaran_bulanan
            $this->db->where('tahun', $thn)->where('deleted_at IS NULL');
            if ($hId > 0) {
                $this->db->where('header_id', $hId);
            } else if (!empty($subKode)) {
                $this->db->where('kode_sub_kegiatan', $subKode);
                if (!empty($header['id_instansi'])) {
                    $this->db->where('id_instansi', (int)$header['id_instansi']);
                }
            }
            $rakRows = $this->db->get('dpa_rak_rincian')->result_array();

            if (!empty($rakRows)) {
                $targetAng = [
                    'jan' => 0, 'feb' => 0, 'mar' => 0, 'apr' => 0,
                    'mei' => 0, 'jun' => 0, 'jul' => 0, 'ags' => 0,
                    'sep' => 0, 'okt' => 0, 'nov' => 0, 'des' => 0,
                    'total_anggaran' => 0
                ];
                foreach ($rakRows as $r) {
                    $targetAng['jan'] += (float)$r['jan'];
                    $targetAng['feb'] += (float)$r['feb'];
                    $targetAng['mar'] += (float)$r['mar'];
                    $targetAng['apr'] += (float)$r['apr'];
                    $targetAng['mei'] += (float)$r['mei'];
                    $targetAng['jun'] += (float)$r['jun'];
                    $targetAng['jul'] += (float)$r['jul'];
                    $targetAng['ags'] += (float)($r['ags'] ?? ($r['agu'] ?? 0));
                    $targetAng['sep'] += (float)$r['sep'];
                    $targetAng['okt'] += (float)$r['okt'];
                    $targetAng['nov'] += (float)$r['nov'];
                    $targetAng['des'] += (float)$r['des'];
                    $targetAng['total_anggaran'] += (float)$r['total_rak'];
                }
            } else if (!empty($header['total_belanja'])) {
                $mShare = (float)$header['total_belanja'] / 12;
                $targetAng = [
                    'jan' => $mShare, 'feb' => $mShare, 'mar' => $mShare, 'apr' => $mShare,
                    'mei' => $mShare, 'jun' => $mShare, 'jul' => $mShare, 'ags' => $mShare,
                    'sep' => $mShare, 'okt' => $mShare, 'nov' => $mShare, 'des' => $mShare,
                    'total_anggaran' => (float)$header['total_belanja']
                ];
            }
        }

        // 2. Realisasi Anggaran Bulanan
        $realAng = null;
        if ($hId > 0) {
            $realAng = $this->db->where('deleted_at IS NULL')
                ->where('header_id', $hId)
                ->where('tahun', $thn)
                ->get('realisasi_renaksi_anggaran_bulanan')
                ->row_array();
        }
        if (!$realAng && !empty($subKode)) {
            $this->db->where('deleted_at IS NULL')
                ->where('kode_sub_kegiatan', $subKode)
                ->where('tahun', $thn);
            if (!empty($header['id_instansi'])) {
                $this->db->where('id_instansi', (int)$header['id_instansi']);
            }
            $realAng = $this->db->get('realisasi_renaksi_anggaran_bulanan')->row_array();
        }

        $monthKeys = ['jan','feb','mar','apr','mei','jun','jul','ags','sep','okt','nov','des'];
        $monthNames = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
        $bulananList = [];
        $runningReal = 0;
        for ($m = 0; $m < 12; $m++) {
            $k = $monthKeys[$m];
            $tVal = $targetAng ? (float)(isset($targetAng[$k]) ? $targetAng[$k] : ($k === 'ags' && isset($targetAng['agu']) ? $targetAng['agu'] : 0)) : 0;
            $rVal = ($realAng && isset($realAng[$k]) && $realAng[$k] !== null && $realAng[$k] !== '') ? (float)$realAng[$k] : null;
            if ($rVal !== null) {
                $runningReal += $rVal;
            }
            $bulananList[] = [
                'bulanIdx' => $m,
                'bulanNama' => $monthNames[$m],
                'target' => $tVal,
                'realisasi' => $rVal,
                'saldoAkumulasi' => $runningReal
            ];
        }

        // 3. Target & Realisasi Indikator
        $targetInds = $this->db->where('deleted_at IS NULL')
            ->group_start()
                ->where('header_id', $hId)
                ->or_group_start()
                    ->where('entity_code', $subKode)
                    ->where('tahun', $thn)
                ->group_end()
            ->group_end()
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get('target_renaksi_indikator')
            ->result_array();

        $realInds = $this->db->where('deleted_at IS NULL')
            ->group_start()
                ->where('header_id', $hId)
                ->or_group_start()
                    ->where('entity_code', $subKode)
                    ->where('tahun', $thn)
                ->group_end()
            ->group_end()
            ->get('realisasi_renaksi_indikator')
            ->result_array();

        $realIndMap = [];
        foreach ($realInds as $ri) {
            if ($ri['indikator_id']) {
                $realIndMap[$ri['indikator_id']] = $ri;
            }
        }

        $indikatorDetailList = [];
        foreach ($targetInds as $ti) {
            $indId = (int)$ti['id'];
            $ri = isset($realIndMap[$indId]) ? $realIndMap[$indId] : null;
            $indikatorDetailList[] = [
                'id' => $indId,
                'uraian' => $ti['uraian_indikator'],
                'satuan' => $ti['satuan'],
                'targetTahunan' => (float)$ti['target_tahunan'],
                'tw' => [
                    ['target' => $ti['tw1'] !== null ? (float)$ti['tw1'] : null, 'realisasi' => $ri && $ri['tw1'] !== null ? (float)$ri['tw1'] : null],
                    ['target' => $ti['tw2'] !== null ? (float)$ti['tw2'] : null, 'realisasi' => $ri && $ri['tw2'] !== null ? (float)$ri['tw2'] : null],
                    ['target' => $ti['tw3'] !== null ? (float)$ti['tw3'] : null, 'realisasi' => $ri && $ri['tw3'] !== null ? (float)$ri['tw3'] : null],
                    ['target' => $ti['tw4'] !== null ? (float)$ti['tw4'] : null, 'realisasi' => $ri && $ri['tw4'] !== null ? (float)$ri['tw4'] : null]
                ]
            ];
        }

        echo json_encode([
            'status' => 'success',
            'data' => [
                'header' => $header,
                'bulanan' => $bulananList,
                'indikators' => $indikatorDetailList,
                'bulanAktif' => $bulanIdx
            ]
        ]);
    }

    public function SaveRealisasiSubKegiatan() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $header_id = (int)$this->input->post('header_id', TRUE);
            $kode_sub_kegiatan = trim($this->input->post('kode_sub_kegiatan', TRUE));
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: $this->get_kode_wilayah() ?: '35.73';
            $id_instansi = (int)($this->input->post('id_instansi', TRUE) ?: $this->get_instansi_id() ?: 1);

            $header = null;
            if ($header_id > 0) {
                $header = $this->db->where('id', $header_id)->where('deleted_at IS NULL')->get('belanja_sub_kegiatan_header')->row_array();
            }
            if (!$header && !empty($kode_sub_kegiatan)) {
                $header = $this->db->where('kode_sub_kegiatan', $kode_sub_kegiatan)->where('tahun', $tahun)->where('deleted_at IS NULL')->get('belanja_sub_kegiatan_header')->row_array();
            }
            if ($header) {
                $header_id = (int)$header['id'];
                $kode_sub_kegiatan = $header['kode_sub_kegiatan'];
                $kode_wilayah = $header['kode_wilayah'] ?: $kode_wilayah;
                $id_instansi = $header['id_instansi'] ? (int)$header['id_instansi'] : $id_instansi;
            }

            $bulananReal = $this->input->post('bulanan_realisasi');
            $indikatorsReal = $this->input->post('indikators_realisasi');

            $this->db->trans_begin();
            $now = date('Y-m-d H:i:s');

            // 1. Simpan Realisasi Anggaran Bulanan
            if (!empty($bulananReal) && is_array($bulananReal)) {
                $monthKeys = ['jan','feb','mar','apr','mei','jun','jul','ags','sep','okt','nov','des'];
                $mVal = [];
                $totReal = 0;
                foreach ($monthKeys as $mk) {
                    $val = isset($bulananReal[$mk]) && $bulananReal[$mk] !== '' && $bulananReal[$mk] !== null ? (float)$bulananReal[$mk] : 0;
                    $mVal[$mk] = $val;
                    $totReal += $val;
                }

                $existAng = null;
                if ($header_id > 0) {
                    $existAng = $this->db->where('deleted_at IS NULL')
                        ->where('header_id', $header_id)
                        ->where('tahun', $tahun)
                        ->get('realisasi_renaksi_anggaran_bulanan')
                        ->row_array();
                }
                if (!$existAng && !empty($kode_sub_kegiatan)) {
                    $this->db->where('deleted_at IS NULL')
                        ->where('kode_sub_kegiatan', $kode_sub_kegiatan)
                        ->where('tahun', $tahun);
                    if ($id_instansi > 0) {
                        $this->db->where('id_instansi', $id_instansi);
                    }
                    $existAng = $this->db->get('realisasi_renaksi_anggaran_bulanan')->row_array();
                }

                $angData = [
                    'header_id' => $header_id,
                    'kode_wilayah' => $kode_wilayah,
                    'tahun' => $tahun,
                    'id_instansi' => $id_instansi,
                    'kode_sub_kegiatan' => $kode_sub_kegiatan,
                    'jan' => $mVal['jan'], 'feb' => $mVal['feb'], 'mar' => $mVal['mar'],
                    'apr' => $mVal['apr'], 'mei' => $mVal['mei'], 'jun' => $mVal['jun'],
                    'jul' => $mVal['jul'], 'ags' => $mVal['ags'], 'sep' => $mVal['sep'],
                    'okt' => $mVal['okt'], 'nov' => $mVal['nov'], 'des' => $mVal['des'],
                    'total_realisasi' => $totReal,
                    'updated_at' => $now
                ];

                if ($existAng) {
                    $this->db->where('id', $existAng['id'])->update('realisasi_renaksi_anggaran_bulanan', $angData);
                } else {
                    $angData['created_at'] = $now;
                    $this->db->insert('realisasi_renaksi_anggaran_bulanan', $angData);
                }
            }

            // 2. Simpan Realisasi Indikators (Triwulan)
            if (!empty($indikatorsReal) && is_array($indikatorsReal)) {
                foreach ($indikatorsReal as $ir) {
                    $indId = isset($ir['indikator_id']) ? (int)$ir['indikator_id'] : (isset($ir['id']) ? (int)$ir['id'] : 0);
                    $tw1 = (isset($ir['tw1']) && $ir['tw1'] !== '' && $ir['tw1'] !== null) ? (float)$ir['tw1'] : null;
                    $tw2 = (isset($ir['tw2']) && $ir['tw2'] !== '' && $ir['tw2'] !== null) ? (float)$ir['tw2'] : null;
                    $tw3 = (isset($ir['tw3']) && $ir['tw3'] !== '' && $ir['tw3'] !== null) ? (float)$ir['tw3'] : null;
                    $tw4 = (isset($ir['tw4']) && $ir['tw4'] !== '' && $ir['tw4'] !== null) ? (float)$ir['tw4'] : null;

                    if ($indId <= 0) continue;

                    $existInd = $this->db->where('deleted_at IS NULL')
                        ->where('indikator_id', $indId)
                        ->where('tahun', $tahun)
                        ->get('realisasi_renaksi_indikator')
                        ->row_array();

                    $realIndRow = [
                        'indikator_id' => $indId,
                        'header_id' => $header_id,
                        'kode_wilayah' => $kode_wilayah,
                        'tahun' => $tahun,
                        'id_instansi' => $id_instansi,
                        'level_type' => 'sub_kegiatan',
                        'entity_code' => $kode_sub_kegiatan,
                        'tw1' => $tw1,
                        'tw2' => $tw2,
                        'tw3' => $tw3,
                        'tw4' => $tw4,
                        'updated_at' => $now
                    ];

                    if ($existInd) {
                        $this->db->where('id', $existInd['id'])->update('realisasi_renaksi_indikator', $realIndRow);
                    } else {
                        $realIndRow['created_at'] = $now;
                        $this->db->insert('realisasi_renaksi_indikator', $realIndRow);
                    }
                }
            }

            if ($this->db->trans_status() === FALSE) {
                $this->db->trans_rollback();
                throw new Exception('Gagal menyimpan realisasi ke database.');
            } else {
                $this->db->trans_commit();
                echo json_encode([
                    'status' => 'success',
                    'message' => 'Realisasi Renaksi Sasaran Sub Kegiatan berhasil disimpan!'
                ]);
            }
        } catch (Exception $e) {
            $this->db->trans_rollback();
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    public function SaveRealisasiHierarchy() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $level_type = $this->input->post('level_type', TRUE);
            $entity_code = trim($this->input->post('entity_code', TRUE));
            $tahun = (int)($this->input->post('tahun', TRUE) ?: date('Y'));
            $kode_wilayah = $this->input->post('kode_wilayah', TRUE) ?: $this->get_kode_wilayah() ?: '35.73';
            $id_instansi = (int)($this->input->post('id_instansi', TRUE) ?: $this->get_instansi_id() ?: 1);
            $tw1 = ($this->input->post('tw1', TRUE) !== '' && $this->input->post('tw1', TRUE) !== null) ? (float)$this->input->post('tw1', TRUE) : null;
            $tw2 = ($this->input->post('tw2', TRUE) !== '' && $this->input->post('tw2', TRUE) !== null) ? (float)$this->input->post('tw2', TRUE) : null;
            $tw3 = ($this->input->post('tw3', TRUE) !== '' && $this->input->post('tw3', TRUE) !== null) ? (float)$this->input->post('tw3', TRUE) : null;
            $tw4 = ($this->input->post('tw4', TRUE) !== '' && $this->input->post('tw4', TRUE) !== null) ? (float)$this->input->post('tw4', TRUE) : null;

            if (empty($level_type) || empty($entity_code)) {
                throw new Exception('Data level atau kode entitas tidak valid.');
            }

            $this->db->trans_begin();
            $now = date('Y-m-d H:i:s');

            $exist = $this->db->where('deleted_at IS NULL')
                ->where('level_type', $level_type)
