        if (!in_array('Kepegawaian', $listUrusan)) $listUrusan[] = 'Kepegawaian';
        $Data['ListUrusan'] = $listUrusan;

        // Ambil Grouped Data otomatis dari Realisasi Renaksi & Kebijakan Sasaran Renstra
