            ]);
        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    public function DeleteCapaianProgramKegiatan() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $id = (int)$this->input->post('id', TRUE);
            if ($id <= 0) throw new Exception('ID data tidak valid.');

            // Soft delete parent and its sub-kegiatans
            $this->db->where('id', $id)->or_where('parent_id', $id)->update('lkpj_capaian_program_kegiatan', [
                'deleted_at' => date('Y-m-d H:i:s')
            ]);

            echo json_encode(['status' => 'success', 'message' => 'Data Capaian Program/Kegiatan berhasil dihapus.']);
        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    // ================================================================
    // 3. E-LKPJ: PENGISIAN TINJUT REKOMENDASI DPRD N-1
    // ================================================================

    private function _ensure_tinjut_dprd_table() {
        if (!$this->db->table_exists('lkpj_rekomendasi_dprd_master')) {
            $this->db->query("CREATE TABLE IF NOT EXISTS `lkpj_rekomendasi_dprd_master` (
              `id` INT(11) NOT NULL AUTO_INCREMENT,
              `kodewilayah` VARCHAR(20) DEFAULT '35.12',
              `instansi_id` INT(11) DEFAULT 0,
              `tahun` INT(4) NOT NULL DEFAULT 2026,
              `rekomendasi` TEXT NOT NULL,
              `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
              `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
              `deleted_at` DATETIME DEFAULT NULL,
              PRIMARY KEY (`id`),
              INDEX `idx_rekom_daerah` (`kodewilayah`, `tahun`, `instansi_id`, `deleted_at`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        } else {
            if (!$this->db->field_exists('instansi_id', 'lkpj_rekomendasi_dprd_master')) {
                $this->db->query("ALTER TABLE `lkpj_rekomendasi_dprd_master` ADD COLUMN `instansi_id` INT(11) DEFAULT 0 AFTER `kodewilayah`, ADD INDEX (`instansi_id`)");
            }
        }

        if (!$this->db->table_exists('lkpj_tinjut_rekomendasi_dprd')) {
            $this->db->query("CREATE TABLE IF NOT EXISTS `lkpj_tinjut_rekomendasi_dprd` (
              `id` INT(11) NOT NULL AUTO_INCREMENT,
              `rekomendasi_id` INT(11) DEFAULT NULL,
              `kodewilayah` VARCHAR(20) DEFAULT '35.12',
              `instansi_id` INT(11) DEFAULT 1,
              `tahun` INT(4) NOT NULL DEFAULT 2026,
              `rekomendasi` TEXT DEFAULT NULL,
              `tindak_lanjut` TEXT DEFAULT NULL,
              `tujuan_masalah` TEXT DEFAULT NULL,
              `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
              `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
              `deleted_at` DATETIME DEFAULT NULL,
              PRIMARY KEY (`id`),
              INDEX `idx_tr_filter` (`tahun`, `instansi_id`, `deleted_at`),
              INDEX `idx_tr_rekom` (`rekomendasi_id`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        } else {
            if (!$this->db->field_exists('rekomendasi_id', 'lkpj_tinjut_rekomendasi_dprd')) {
                $this->db->query("ALTER TABLE `lkpj_tinjut_rekomendasi_dprd` ADD COLUMN `rekomendasi_id` INT(11) DEFAULT NULL AFTER `id`, ADD INDEX (`rekomendasi_id`)");
            }
        }

        // Seed master if master table is empty
        $countMaster = $this->db->where('deleted_at IS NULL')->count_all_results('lkpj_rekomendasi_dprd_master');
        if ($countMaster == 0) {
            $old_items = $this->db->where('deleted_at IS NULL')->group_by(['tahun', 'rekomendasi'])->get('lkpj_tinjut_rekomendasi_dprd')->result_array();
            if (!empty($old_items)) {
                foreach ($old_items as $old) {
                    if (!empty(trim($old['rekomendasi']))) {
                        $this->db->insert('lkpj_rekomendasi_dprd_master', [
                            'kodewilayah' => !empty($old['kodewilayah']) ? $old['kodewilayah'] : '35.12',
                            'instansi_id' => !empty($old['instansi_id']) ? (int)$old['instansi_id'] : 0,
                            'tahun' => !empty($old['tahun']) ? (int)$old['tahun'] : 2026,
                            'rekomendasi' => trim($old['rekomendasi']),
                            'created_at' => date('Y-m-d H:i:s'),
                            'updated_at' => date('Y-m-d H:i:s')
                        ]);
                        $m_id = $this->db->insert_id();
                        $this->db->where('rekomendasi', $old['rekomendasi'])->update('lkpj_tinjut_rekomendasi_dprd', ['rekomendasi_id' => $m_id]);
                    }
                }
            } else {
                $seeds = [
                    'Terhadap kegiatan intervensi untuk menekan tingkat ketimpangan ekonomi, tentunya patut direkomendasikan dilakukan evaluasi pada setiap sector/cluster kebijakan strategis, agar dicapai kegiatan maupun kebijakan inovatif yang berfokus pada penurunan ketimpangan ekonomi, dengan memperhatikan Kebijakan inovatif yang mengintegrasikan program prioritas Kabupaten, Provinsi dan Nasional.',
                    'Bahwa dalam rangka mewujudkan pertumbuhan ekonomi Situbondo yang inklusif, penting untuk direkomendasikan adanya pertumbuhan pada sektor- sektor kerakyatan yang dominan menyerap tenaga kerja, seperti pertanian dan kehutanan dan perikanan dengan strategi kebijakan yang progresif (intensifikasi dan ekstensifikasi produksi, pemasaran, teknologi, pemberdayaan penyuluh, sarana irigasi, aplikasi pertanian organic).'
                ];
                foreach ($seeds as $s) {
                    $this->db->insert('lkpj_rekomendasi_dprd_master', [
                        'kodewilayah' => '35.12',
                        'instansi_id' => 0,
                        'tahun' => 2026,
                        'rekomendasi' => $s,
                        'created_at' => date('Y-m-d H:i:s'),
                        'updated_at' => date('Y-m-d H:i:s')
                    ]);
                }
            }
        }

        // Synchronize instansi_id in tinjut with master when master has specific instansi_id
        $this->db->query("UPDATE `lkpj_tinjut_rekomendasi_dprd` t 
            INNER JOIN `lkpj_rekomendasi_dprd_master` m ON t.rekomendasi_id = m.id 
            SET t.instansi_id = m.instansi_id 
            WHERE t.instansi_id != m.instansi_id AND m.instansi_id > 0 AND m.deleted_at IS NULL");
    }

    private function _get_tinjut_rekomendasi_dprd_items($tahun, $instansi_id, $KodeWilayah = null, $is_role_4 = false) {
        $this->_ensure_tinjut_dprd_table();

        // Get map of instansi filtered by region if set
        $this->db->select('id, nama')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) {
            $this->db->where('kodewilayah', $KodeWilayah);
        }
        $instList = $this->db->get('akun_instansi')->result_array();
        $instMap = [];
        foreach ($instList as $ins) {
            $instMap[(int)$ins['id']] = $ins['nama'];
        }

        $this->db->where('deleted_at IS NULL');
        if ($tahun > 0) $this->db->where('tahun', (int)$tahun);
        if (!empty($KodeWilayah)) {
            $this->db->where('kodewilayah', $KodeWilayah);
        }

        // If filtering for a specific instansi
        if ($instansi_id > 0) {
            $this->db->group_start()
                ->where('instansi_id', (int)$instansi_id)
                ->or_where('instansi_id', 0)
                ->or_where('instansi_id IS NULL')
                ->group_end();
        }

        $masters = $this->db->order_by('id', 'ASC')->get('lkpj_rekomendasi_dprd_master')->result_array();

        $this->db->where('deleted_at IS NULL');
        if ($tahun > 0) $this->db->where('tahun', (int)$tahun);
        if (!empty($KodeWilayah)) {
            $this->db->where('kodewilayah', $KodeWilayah);
        }
        if ($instansi_id > 0) $this->db->where('instansi_id', (int)$instansi_id);
        $tinjuts = $this->db->get('lkpj_tinjut_rekomendasi_dprd')->result_array();

        $tinjut_by_rekom = [];
        $tinjut_by_text = [];
        foreach ($tinjuts as $t) {
            if (!empty($t['rekomendasi_id'])) {
                $tinjut_by_rekom[$t['rekomendasi_id']] = $t;
            }
            if (!empty($t['rekomendasi'])) {
                $tinjut_by_text[trim($t['rekomendasi'])] = $t;
            }
        }

        $items = [];
        $usedTinjutIds = [];

        foreach ($masters as $m) {
            $matched = null;
            if (!empty($m['id']) && isset($tinjut_by_rekom[$m['id']])) {
                $matched = $tinjut_by_rekom[$m['id']];
            } elseif (!empty($m['rekomendasi']) && isset($tinjut_by_text[trim($m['rekomendasi'])])) {
                $matched = $tinjut_by_text[trim($m['rekomendasi'])];
            }

            if ($matched) {
                $usedTinjutIds[] = $matched['id'];
            }

            $tagId = !empty($m['instansi_id']) ? (int)$m['instansi_id'] : 0;
            $tagNama = ($tagId > 0 && isset($instMap[$tagId])) ? $instMap[$tagId] : 'Semua Perangkat Daerah';

            $items[] = [
                'id' => $matched ? (int)$matched['id'] : 0,
                'rekomendasi_id' => (int)$m['id'],
                'target_instansi_id' => $tagId,
                'target_instansi_nama' => $tagNama,
                'kodewilayah' => $m['kodewilayah'],
                'instansi_id' => (int)$instansi_id,
                'tahun' => (int)$m['tahun'],
                'rekomendasi' => $m['rekomendasi'],
                'tindak_lanjut' => $matched ? ($matched['tindak_lanjut'] ?: '') : '',
                'tujuan_masalah' => $matched ? ($matched['tujuan_masalah'] ?: '') : '',
                'is_master' => 1
            ];
        }

        // Standalone tinjut records
        foreach ($tinjuts as $t) {
            if (!in_array($t['id'], $usedTinjutIds)) {
                if (!empty($t['rekomendasi_id'])) {
                    $mRow = $this->db->where('id', (int)$t['rekomendasi_id'])->where('deleted_at IS NULL')->get('lkpj_rekomendasi_dprd_master')->row_array();
                    if ($mRow) {
                        if ($instansi_id > 0 && !empty($mRow['instansi_id']) && (int)$mRow['instansi_id'] !== (int)$instansi_id) {
                            continue;
                        }
                    }
                }
                if (!empty($KodeWilayah) && !empty($t['kodewilayah']) && $t['kodewilayah'] !== $KodeWilayah) {
                    continue;
                }
                $tagId = !empty($t['instansi_id']) ? (int)$t['instansi_id'] : 0;
                $tagNama = ($tagId > 0 && isset($instMap[$tagId])) ? $instMap[$tagId] : 'Semua Perangkat Daerah';

                $items[] = [
                    'id' => (int)$t['id'],
                    'rekomendasi_id' => !empty($t['rekomendasi_id']) ? (int)$t['rekomendasi_id'] : 0,
                    'target_instansi_id' => $tagId,
                    'target_instansi_nama' => $tagNama,
                    'kodewilayah' => $t['kodewilayah'],
                    'instansi_id' => (int)$t['instansi_id'],
                    'tahun' => (int)$t['tahun'],
                    'rekomendasi' => $t['rekomendasi'] ?: '',
                    'tindak_lanjut' => $t['tindak_lanjut'] ?: '',
                    'tujuan_masalah' => $t['tujuan_masalah'] ?: '',
                    'is_master' => 0
                ];
            }
        }

        return $items;
    }

    public function PengisianTinjutRekomendasiDPRDn1() {
        $Header['Halaman'] = 'Pengisian Tindak Lanjut Rekomendasi DPRD n-1';
        
        $KodeWilayah = $this->get_kode_wilayah();
        $instansi_id = $this->get_instansi_id();
        $is_role_4 = $this->is_role_4();
        $tahun = (int)($this->input->get('tahun', TRUE) ?: (isset($_SESSION['Tahun']) ? $_SESSION['Tahun'] : 2026));
        $filter_instansi = $this->input->get('instansi_id', TRUE);
        if (empty($filter_instansi) && isset($_SESSION['TempInstansiId']) && !empty($_SESSION['TempInstansiId'])) {
            $filter_instansi = $_SESSION['TempInstansiId'];
        }

        if ($is_role_4 && $instansi_id) {
            $filter_instansi = $instansi_id;
        }

        $is_logged_in = $this->is_logged_in();
        $Data['IsLoggedIn'] = $is_logged_in;
        $Data['KodeWilayah'] = $KodeWilayah;
        $Data['NamaWilayah'] = '';
        $Data['IsRole4'] = $is_role_4;
        $Data['IsDaerah'] = $is_logged_in && !$is_role_4;
        $Data['InstansiId'] = $instansi_id;
        $Data['ControllerName'] = 'Instansi';

        if (!empty($KodeWilayah)) {
            $wilayah = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            $Data['NamaWilayah'] = $wilayah ? $wilayah['Nama'] : '';
        }

        $this->db->select('id, nama')->from('akun_instansi')->where('deleted_at IS NULL');
        if (!empty($KodeWilayah)) {
            $this->db->where('kodewilayah', $KodeWilayah);
        }
        $Data['ListInstansi'] = $this->db->order_by('nama', 'ASC')->get()->result_array();
        $Data['ListTahun'] = [2027, 2026, 2025, 2024, 2023];
        $Data['TahunAktif'] = (int)$tahun;
        $activeInstansi = $filter_instansi !== null && $filter_instansi !== '' ? (int)$filter_instansi : ($is_role_4 ? (int)$instansi_id : 0);
        $Data['FilterInstansi'] = $activeInstansi;
        $Data['filterInstansi'] = $activeInstansi;
        $Data['ActiveInstansiId'] = $activeInstansi;

        // Data Provinsi untuk filter
        $Data['Provinsi'] = $this->db
            ->where("Kode LIKE '__'")
            ->order_by('Nama')
            ->get('kodewilayah')
            ->result_array();

        if (!$is_logged_in && empty($KodeWilayah)) {
            $items = [];
        } else {
            $items = $this->_get_tinjut_rekomendasi_dprd_items($tahun, $Data['FilterInstansi'], $KodeWilayah, $is_role_4);
        }

        $filled = 0;
        foreach ($items as $it) {
            if (!empty(trim($it['tindak_lanjut'])) && !empty(trim($it['tujuan_masalah']))) {
                $filled++;
            }
        }
        $total = count($items);
        $pending = $total - $filled;

        $Data['Items'] = $items;
        $Data['Stats'] = [
            'total' => $total,
            'filled' => $filled,
            'pending' => $pending
        ];

        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/PengisianTinjutRekomendasiDPRDn1', $Data);
    }

    // Alias method
    public function PengisianTinjutRekomendasiDPRD() {
        $this->PengisianTinjutRekomendasiDPRDn1();
    }

    public function GetTinjutRekomendasiDPRD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        $tahun = (int)($this->input->post('tahun', TRUE) ?: 2026);
        $is_role_4 = $this->is_role_4();
        $KodeWilayah = $this->get_kode_wilayah();

        $post_instansi = $this->input->post('instansi_id', TRUE);
        if ($post_instansi !== null && $post_instansi !== '') {
            $instansi_id = (int)$post_instansi;
        } else {
            $instansi_id = $is_role_4 ? (int)($this->get_instansi_id() ?: 0) : 0;
        }

        $items = $this->_get_tinjut_rekomendasi_dprd_items($tahun, $instansi_id, $KodeWilayah, $is_role_4);

        $filled = 0;
        foreach ($items as $it) {
            if (!empty(trim($it['tindak_lanjut'])) && !empty(trim($it['tujuan_masalah']))) {
                $filled++;
            }
        }
        $total = count($items);
        $pending = $total - $filled;

        echo json_encode([
            'status' => 'success',
            'data' => $items,
            'stats' => [
                'total' => $total,
                'filled' => $filled,
                'pending' => $pending
            ]
        ]);
    }

    public function SaveTinjutRekomendasiDPRD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $this->_ensure_tinjut_dprd_table();

            $id = (int)$this->input->post('id', TRUE);
            $rekomendasi_id = (int)$this->input->post('rekomendasi_id', TRUE);
            $target_instansi_id = (int)$this->input->post('target_instansi_id', TRUE);
            $tahun = (int)($this->input->post('tahun', TRUE) ?: 2026);
            $instansi_id = (int)($this->input->post('instansi_id', TRUE) ?: ($this->get_instansi_id() ?: 1));
            $kode_wilayah = $this->get_kode_wilayah() ?: '35.12';
            $rekomendasi = trim($this->input->post('rekomendasi', TRUE));
            $tindak_lanjut = trim($this->input->post('tindak_lanjut', TRUE));
            $tujuan_masalah = trim($this->input->post('tujuan_masalah', TRUE));
            $action_type = $this->input->post('action_type', TRUE);

            if ($action_type === 'daerah_master') {
                if (empty($rekomendasi)) {
                    throw new Exception('Uraian Rekomendasi DPRD wajib diisi.');
                }

                // If rekomendasi_id is 0 but $id > 0, check if that tinjut row has a master
                if ($rekomendasi_id <= 0 && $id > 0) {
                    $tRow = $this->db->where('id', $id)->get('lkpj_tinjut_rekomendasi_dprd')->row_array();
                    if ($tRow && !empty($tRow['rekomendasi_id'])) {
                        $rekomendasi_id = (int)$tRow['rekomendasi_id'];
                    }
                }

                if ($rekomendasi_id > 0) {
                    $oldMaster = $this->db->where('id', $rekomendasi_id)->get('lkpj_rekomendasi_dprd_master')->row_array();
                    $targetChanged = ($oldMaster && (int)$oldMaster['instansi_id'] !== (int)$target_instansi_id);

                    $this->db->where('id', $rekomendasi_id)->update('lkpj_rekomendasi_dprd_master', [
                        'rekomendasi' => $rekomendasi,
                        'instansi_id' => $target_instansi_id,
                        'tahun' => $tahun,
                        'kodewilayah' => $kode_wilayah,
                        'updated_at' => date('Y-m-d H:i:s')
                    ]);

                    $tinjutUpdate = [
                        'instansi_id' => $target_instansi_id,
                        'rekomendasi' => $rekomendasi,
                        'tahun' => $tahun,
                        'kodewilayah' => $kode_wilayah,
                        'updated_at' => date('Y-m-d H:i:s')
                    ];
                    if ($targetChanged) {
                        $tinjutUpdate['tindak_lanjut'] = null;
                        $tinjutUpdate['tujuan_masalah'] = null;
                    }

                    // Sync all tinjut records for this master to the new target_instansi_id
                    $this->db->where('rekomendasi_id', $rekomendasi_id)->update('lkpj_tinjut_rekomendasi_dprd', $tinjutUpdate);

                    if ($id > 0) {
                        $singleUpdate = [
                            'rekomendasi_id' => $rekomendasi_id,
                            'instansi_id' => $target_instansi_id,
                            'rekomendasi' => $rekomendasi,
                            'updated_at' => date('Y-m-d H:i:s')
                        ];
                        if ($targetChanged) {
                            $singleUpdate['tindak_lanjut'] = null;
                            $singleUpdate['tujuan_masalah'] = null;
                        }
                        $this->db->where('id', $id)->update('lkpj_tinjut_rekomendasi_dprd', $singleUpdate);
                    }

                    $msg = 'Rekomendasi DPRD Daerah berhasil diperbarui.';
                } else {
                    $existingMaster = $this->db->where('tahun', $tahun)
                        ->where('kodewilayah', $kode_wilayah)
                        ->where('rekomendasi', $rekomendasi)
                        ->where('deleted_at IS NULL')
                        ->get('lkpj_rekomendasi_dprd_master')
                        ->row_array();

                    if ($existingMaster) {
                        $rekomendasi_id = (int)$existingMaster['id'];
                        $targetChanged = ((int)$existingMaster['instansi_id'] !== (int)$target_instansi_id);

                        $this->db->where('id', $rekomendasi_id)->update('lkpj_rekomendasi_dprd_master', [
                            'instansi_id' => $target_instansi_id,
                            'updated_at' => date('Y-m-d H:i:s')
                        ]);

                        $tinjutUpdate = [
                            'instansi_id' => $target_instansi_id,
                            'rekomendasi' => $rekomendasi,
                            'updated_at' => date('Y-m-d H:i:s')
                        ];
                        if ($targetChanged) {
                            $tinjutUpdate['tindak_lanjut'] = null;
                            $tinjutUpdate['tujuan_masalah'] = null;
                        }
                        $this->db->where('rekomendasi_id', $rekomendasi_id)->update('lkpj_tinjut_rekomendasi_dprd', $tinjutUpdate);
                    } else {
                        $this->db->insert('lkpj_rekomendasi_dprd_master', [
                            'kodewilayah' => $kode_wilayah,
                            'instansi_id' => $target_instansi_id,
                            'tahun' => $tahun,
                            'rekomendasi' => $rekomendasi,
                            'created_at' => date('Y-m-d H:i:s'),
                            'updated_at' => date('Y-m-d H:i:s')
                        ]);
                        $rekomendasi_id = $this->db->insert_id();
                    }

                    if ($id > 0) {
                        $this->db->where('id', $id)->update('lkpj_tinjut_rekomendasi_dprd', [
                            'rekomendasi_id' => $rekomendasi_id,
                            'instansi_id' => $target_instansi_id,
                            'rekomendasi' => $rekomendasi,
                            'tindak_lanjut' => null,
                            'tujuan_masalah' => null,
                            'updated_at' => date('Y-m-d H:i:s')
                        ]);
                    }

                    $msg = 'Rekomendasi DPRD Daerah berhasil disimpan.';
                }
            } else {
                // Instansi input Tindak Lanjut & Tujuan / Masalah
                if (empty($tindak_lanjut)) {
                    throw new Exception('Tindak Lanjut yang dilakukan wajib diisi.');
                }
                if (empty($tujuan_masalah)) {
                    throw new Exception('Tujuan / Masalah yang diselesaikan wajib diisi.');
                }

                $existing = null;
                if ($id > 0) {
                    $existing = $this->db->where('id', $id)->where('deleted_at IS NULL')->get('lkpj_tinjut_rekomendasi_dprd')->row_array();
                }
                if (!$existing && $rekomendasi_id > 0) {
                    $existing = $this->db->where('rekomendasi_id', $rekomendasi_id)
                        ->where('instansi_id', $instansi_id)
                        ->where('tahun', $tahun)
                        ->where('deleted_at IS NULL')
                        ->get('lkpj_tinjut_rekomendasi_dprd')->row_array();
                }

                if (empty($rekomendasi) && $rekomendasi_id > 0) {
                    $masterRow = $this->db->where('id', $rekomendasi_id)->get('lkpj_rekomendasi_dprd_master')->row_array();
                    if ($masterRow) {
                        $rekomendasi = $masterRow['rekomendasi'];
                    }
                }

                if ($existing) {
                    $saveData = [
                        'rekomendasi_id' => $rekomendasi_id ?: $existing['rekomendasi_id'],
                        'tindak_lanjut' => $tindak_lanjut,
                        'tujuan_masalah' => $tujuan_masalah,
                        'updated_at' => date('Y-m-d H:i:s')
                    ];
                    if (!empty($rekomendasi)) {
                        $saveData['rekomendasi'] = $rekomendasi;
                    }
                    $this->db->where('id', $existing['id'])->update('lkpj_tinjut_rekomendasi_dprd', $saveData);
                    $id = $existing['id'];
                    $msg = 'Tindak Lanjut Rekomendasi DPRD berhasil disimpan.';
                } else {
                    $saveData = [
                        'rekomendasi_id' => $rekomendasi_id,
                        'kodewilayah' => $kode_wilayah,
                        'instansi_id' => $instansi_id,
                        'tahun' => $tahun,
                        'rekomendasi' => $rekomendasi,
                        'tindak_lanjut' => $tindak_lanjut,
                        'tujuan_masalah' => $tujuan_masalah,
                        'created_at' => date('Y-m-d H:i:s'),
                        'updated_at' => date('Y-m-d H:i:s')
                    ];
                    $this->db->insert('lkpj_tinjut_rekomendasi_dprd', $saveData);
                    $id = $this->db->insert_id();
                    $msg = 'Tindak Lanjut Rekomendasi DPRD berhasil disimpan.';
                }
            }

            echo json_encode([
                'status' => 'success',
                'message' => $msg,
                'data' => [
                    'id' => $id,
                    'rekomendasi_id' => $rekomendasi_id
                ]
            ]);
        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    public function DeleteTinjutRekomendasiDPRD() {
        if (!$this->input->is_ajax_request()) {
            show_404();
            return;
        }
        header('Content-Type: application/json');

        try {
            $id = (int)$this->input->post('id', TRUE);
            $rekomendasi_id = (int)$this->input->post('rekomendasi_id', TRUE);
            $is_master = (int)$this->input->post('is_master', TRUE);

            if ($is_master && $rekomendasi_id > 0) {
                $this->db->where('id', $rekomendasi_id)->update('lkpj_rekomendasi_dprd_master', [
                    'deleted_at' => date('Y-m-d H:i:s')
                ]);
                $this->db->where('rekomendasi_id', $rekomendasi_id)->update('lkpj_tinjut_rekomendasi_dprd', [
                    'deleted_at' => date('Y-m-d H:i:s')
                ]);
                $msg = 'Rekomendasi DPRD Daerah berhasil dihapus.';
            } elseif ($id > 0) {
                $this->db->where('id', $id)->update('lkpj_tinjut_rekomendasi_dprd', [
                    'tindak_lanjut' => null,
                    'tujuan_masalah' => null,
                    'updated_at' => date('Y-m-d H:i:s')
                ]);
                $msg = 'Tindak Lanjut instansi berhasil direset.';
            } else {
                throw new Exception('ID data tidak valid.');
            }

            echo json_encode(['status' => 'success', 'message' => $msg]);
        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    // ================================================================
    // 3.4 E-LKPJ: BAB 3.4 BAGIAN A - CAPAIAN KINERJA INDIKATOR KINERJA UTAMA (IKU)
    // ================================================================

    private function ensure_bab3_4a_tables_exist($KodeWilayah = '35.12', $tahun = 2025) {
        $this->db->query("CREATE TABLE IF NOT EXISTS `lkpj_bab3_iku_capaian` (
          `id` int(11) NOT NULL AUTO_INCREMENT,
          `kodewilayah` varchar(13) NOT NULL,
          `tahun` int(4) NOT NULL DEFAULT 2025,
          `iku_id` int(11) DEFAULT NULL,
          `misi_id` int(11) DEFAULT NULL,
          `misi` text NOT NULL,
          `tujuan_id` int(11) DEFAULT NULL,
          `tujuan` text NOT NULL,
          `indikator_iku` text NOT NULL,
          `satuan` varchar(50) DEFAULT 'Indeks',
          `realisasi_2022` decimal(15,3) DEFAULT NULL,
          `realisasi_2023` decimal(15,3) DEFAULT NULL,
          `realisasi_2024` decimal(15,3) DEFAULT NULL,
          `target_2025` decimal(15,3) DEFAULT NULL,
          `realisasi_2025` decimal(15,3) DEFAULT NULL,
          `capaian_2025` decimal(15,3) DEFAULT NULL,
          `urutan` int(11) NOT NULL DEFAULT 0,
          `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
          `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
          `deleted_at` datetime DEFAULT NULL,
          PRIMARY KEY (`id`),
          KEY `idx_wilayah_tahun` (`kodewilayah`, `tahun`, `deleted_at`)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8;");

        $this->db->query("CREATE TABLE IF NOT EXISTS `lkpj_bab3_iku_perkembangan` (
          `id` int(11) NOT NULL AUTO_INCREMENT,
          `kodewilayah` varchar(13) NOT NULL,
          `tahun` int(4) NOT NULL DEFAULT 2025,
          `capaian_id` int(11) DEFAULT NULL,
          `uraian_indikator` varchar(255) NOT NULL,
          `nilai_2021` decimal(15,3) DEFAULT NULL,
          `nilai_2022` decimal(15,3) DEFAULT NULL,
          `nilai_2023` decimal(15,3) DEFAULT NULL,
          `nilai_2024` decimal(15,3) DEFAULT NULL,
          `nilai_2025` decimal(15,3) DEFAULT NULL,
          `narasi` text DEFAULT NULL,
          `urutan` int(11) NOT NULL DEFAULT 0,
          `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
          `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
          `deleted_at` datetime DEFAULT NULL,
          PRIMARY KEY (`id`),
          KEY `idx_wilayah_tahun` (`kodewilayah`, `tahun`, `deleted_at`)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8;");

        // Pastikan kolom narasi, iku_id, dan kolom tahunan dinamis tersedia di tabel
        if ($this->db->table_exists('lkpj_bab3_iku_perkembangan') && !$this->db->field_exists('narasi', 'lkpj_bab3_iku_perkembangan')) {
            $this->db->query("ALTER TABLE `lkpj_bab3_iku_perkembangan` ADD COLUMN `narasi` TEXT DEFAULT NULL AFTER `nilai_2025`");
        }
        if ($this->db->table_exists('lkpj_bab3_iku_perkembangan') && !$this->db->field_exists('iku_id', 'lkpj_bab3_iku_perkembangan')) {
            $this->db->query("ALTER TABLE `lkpj_bab3_iku_perkembangan` ADD COLUMN `iku_id` INT(11) DEFAULT NULL AFTER `tahun`");
        }
        if ($this->db->table_exists('lkpj_bab3_iku_capaian')) {
            if (!$this->db->field_exists('realisasi_2021', 'lkpj_bab3_iku_capaian')) {
                $this->db->query("ALTER TABLE `lkpj_bab3_iku_capaian` ADD COLUMN `realisasi_2021` decimal(15,3) DEFAULT NULL AFTER `satuan`");
            }
            if (!$this->db->field_exists('target', 'lkpj_bab3_iku_capaian')) {
                $this->db->query("ALTER TABLE `lkpj_bab3_iku_capaian` ADD COLUMN `target` decimal(15,3) DEFAULT NULL AFTER `realisasi_2024`");
            }
            if (!$this->db->field_exists('realisasi', 'lkpj_bab3_iku_capaian')) {
                $this->db->query("ALTER TABLE `lkpj_bab3_iku_capaian` ADD COLUMN `realisasi` decimal(15,3) DEFAULT NULL AFTER `target`");
            }
            if (!$this->db->field_exists('capaian', 'lkpj_bab3_iku_capaian')) {
                $this->db->query("ALTER TABLE `lkpj_bab3_iku_capaian` ADD COLUMN `capaian` decimal(15,3) DEFAULT NULL AFTER `realisasi`");
            }
        }
    }

    /**
     * Sinkronisasi dan penarikan data murni dari relasi IKU di RPJMD
     * Menghubungkan tabel iku -> tujuanrpjmd -> misirpjmd secara dinamis per tahun LKPJ
     */
    private function sync_from_rpjmd_iku($KodeWilayah, $tahun) {
        $wil = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
        $namaWilayah = $wil ? ucwords(strtolower($wil['Nama'])) : 'Pemerintah Daerah';

        $ikuRows = $this->db->query("
            SELECT 
                i.id as iku_id,
                i.kodewilayah,
                i.indikator_tujuan,
                i.target_1, i.target_2, i.target_3, i.target_4, i.target_5,
                i.tahun_mulai, i.tahun_akhir,
                t.Id as tujuan_id,
                t.Tujuan,
                m.Id as misi_id,
                m.Misi
            FROM iku i
            LEFT JOIN tujuanrpjmd t ON i.IdTujuan = t.Id AND t.deleted_at IS NULL
            LEFT JOIN misirpjmd m ON t._Id = m.Id AND m.deleted_at IS NULL
            WHERE i.deleted_at IS NULL 
            AND (i.kodewilayah = ? OR i.kodewilayah LIKE ?)
            ORDER BY m.Id ASC, t.Id ASC, i.id ASC
        ", [$KodeWilayah, $KodeWilayah . '%'])->result_array();

        if (empty($ikuRows)) {
            return [
                'itemsCapaian' => [],
                'misiRowspan' => [],
                'tujuanRowspan' => [],
                'itemsPerkembangan' => []
            ];
        }

        $validIkuIds = [];
        $urutan = 1;

        foreach ($ikuRows as $r) {
            $namaIku = trim($r['indikator_tujuan']);
            if (empty($namaIku)) continue;

            $validIkuIds[] = (int)$r['iku_id'];
            $namaMisi = !empty($r['Misi']) ? trim($r['Misi']) : 'Misi Pembangunan ' . $namaWilayah;
            $namaTujuan = !empty($r['Tujuan']) ? trim($r['Tujuan']) : 'Tujuan Pembangunan ' . $namaWilayah;

            // Deteksi satuan cerdas
            $satuan = 'Indeks';
            $lowerInd = strtolower($namaIku);
            if (strpos($lowerInd, '%') !== false || strpos($lowerInd, 'persen') !== false || strpos($lowerInd, 'pertumbuhan') !== false || strpos($lowerInd, 'kemiskinan') !== false) {
                $satuan = '%';
            } elseif (strpos($lowerInd, 'jiwa') !== false || strpos($lowerInd, 'orang') !== false) {
                $satuan = 'Jiwa';
            }

            $n21 = is_numeric($r['target_1']) ? (float)$r['target_1'] : null;
            $n22 = is_numeric($r['target_2']) ? (float)$r['target_2'] : null;
            $n23 = is_numeric($r['target_3']) ? (float)$r['target_3'] : null;
            $n24 = is_numeric($r['target_4']) ? (float)$r['target_4'] : null;
            $n25 = is_numeric($r['target_5']) ? (float)$r['target_5'] : null;

            // Cek data perkembangan yang sudah ada untuk mempertahankan editan user
            $namaPerk = 'Perkembangan ' . $namaIku;
            $existPerk = $this->db->where('kodewilayah', $KodeWilayah)
                                  ->where('tahun', $tahun)
                                  ->group_start()
                                      ->where('iku_id', $r['iku_id'])
                                      ->or_where('uraian_indikator', $namaPerk)
                                      ->or_where('uraian_indikator', $namaIku)
                                  ->group_end()
                                  ->where('deleted_at IS NULL')
                                  ->get('lkpj_bab3_iku_perkembangan')
                                  ->row_array();

            if ($existPerk) {
                $p21 = ($existPerk['nilai_2021'] !== null && $existPerk['nilai_2021'] !== '') ? (float)$existPerk['nilai_2021'] : $n21;
                $p22 = ($existPerk['nilai_2022'] !== null && $existPerk['nilai_2022'] !== '') ? (float)$existPerk['nilai_2022'] : $n22;
                $p23 = ($existPerk['nilai_2023'] !== null && $existPerk['nilai_2023'] !== '') ? (float)$existPerk['nilai_2023'] : $n23;
                $p24 = ($existPerk['nilai_2024'] !== null && $existPerk['nilai_2024'] !== '') ? (float)$existPerk['nilai_2024'] : $n24;
                $p25 = ($existPerk['nilai_2025'] !== null && $existPerk['nilai_2025'] !== '') ? (float)$existPerk['nilai_2025'] : $n25;

                $this->db->where('id', $existPerk['id'])->update('lkpj_bab3_iku_perkembangan', [
                    'iku_id' => $r['iku_id'],
                    'uraian_indikator' => $namaPerk,
                    'nilai_2021' => $p21,
                    'nilai_2022' => $p22,
                    'nilai_2023' => $p23,
                    'nilai_2024' => $p24,
                    'nilai_2025' => $p25,
                    'urutan' => $urutan,
                    'updated_at' => date('Y-m-d H:i:s')
                ]);
                $perkId = $existPerk['id'];
            } else {
                $p21 = $n21; $p22 = $n22; $p23 = $n23; $p24 = $n24; $p25 = $n25;
                $this->db->insert('lkpj_bab3_iku_perkembangan', [
                    'kodewilayah' => $KodeWilayah,
                    'tahun' => $tahun,
                    'iku_id' => $r['iku_id'],
                    'uraian_indikator' => $namaPerk,
                    'nilai_2021' => $p21,
                    'nilai_2022' => $p22,
                    'nilai_2023' => $p23,
                    'nilai_2024' => $p24,
                    'nilai_2025' => $p25,
                    'narasi' => null,
                    'urutan' => $urutan,
                    'created_at' => date('Y-m-d H:i:s')
                ]);
                $perkId = $this->db->insert_id();
            }

            // Hitung target, realisasi, dan capaian dinamis untuk tahun LKPJ aktif ($tahun)
            $targetMap = [2021 => $n21, 2022 => $n22, 2023 => $n23, 2024 => $n24, 2025 => $n25];
            $realisasiMap = [2021 => $p21, 2022 => $p22, 2023 => $p23, 2024 => $p24, 2025 => $p25];

            $targetAktif = $targetMap[$tahun] ?? ($n25 ?: $n21);
            $realisasiAktif = $realisasiMap[$tahun] ?? null;
            $capaianAktif = null;
            if ($targetAktif !== null && $targetAktif > 0 && $realisasiAktif !== null) {
                $capaianAktif = round(($realisasiAktif / $targetAktif) * 100, 2);
            }

            // Sinkronkan ke tabel Capaian IKU
            $existCapaian = $this->db->where('kodewilayah', $KodeWilayah)
                                     ->where('tahun', $tahun)
                                     ->group_start()
                                         ->where('iku_id', $r['iku_id'])
                                         ->or_where('indikator_iku', $namaIku)
                                     ->group_end()
                                     ->where('deleted_at IS NULL')
                                     ->get('lkpj_bab3_iku_capaian')
                                     ->row_array();

            $capaianData = [
                'kodewilayah' => $KodeWilayah,
                'tahun' => $tahun,
                'iku_id' => $r['iku_id'],
                'misi_id' => $r['misi_id'],
                'misi' => $namaMisi,
                'tujuan_id' => $r['tujuan_id'],
                'tujuan' => $namaTujuan,
                'indikator_iku' => $namaIku,
                'satuan' => (!empty($existCapaian['satuan']) && $existCapaian['satuan'] !== 'Indeks') ? $existCapaian['satuan'] : $satuan,
                'realisasi_2021' => $p21,
                'realisasi_2022' => $p22,
                'realisasi_2023' => $p23,
                'realisasi_2024' => $p24,
                'target_2025' => ($n25 !== null ? $n25 : $n21),
                'target' => $targetAktif,
                'realisasi' => $realisasiAktif,
                'capaian' => $capaianAktif,
                'urutan' => $urutan,
                'updated_at' => date('Y-m-d H:i:s')
            ];
            if ($tahun == 2025) {
                $capaianData['realisasi_2025'] = $realisasiAktif;
                $capaianData['capaian_2025'] = $capaianAktif;
            }

            if ($existCapaian) {
                $capaianId = $existCapaian['id'];
                $this->db->where('id', $capaianId)->update('lkpj_bab3_iku_capaian', $capaianData);
            } else {
                $capaianData['created_at'] = date('Y-m-d H:i:s');
                $this->db->insert('lkpj_bab3_iku_capaian', $capaianData);
                $capaianId = $this->db->insert_id();
            }

            // Tautkan capaian_id di perkembangan
            if ($perkId > 0 && $capaianId > 0) {
                $this->db->where('id', $perkId)->update('lkpj_bab3_iku_perkembangan', ['capaian_id' => $capaianId]);
            }

            $urutan++;
        }

        // Soft-delete data lokal yang tidak terdaftar dalam master iku RPJMD agar murni hanya menampilkan IKU RPJMD
        if (!empty($validIkuIds)) {
            $this->db->where('kodewilayah', $KodeWilayah)
                     ->where('tahun', $tahun)
                     ->where_not_in('iku_id', $validIkuIds)
                     ->update('lkpj_bab3_iku_capaian', ['deleted_at' => date('Y-m-d H:i:s')]);

            $this->db->where('kodewilayah', $KodeWilayah)
                     ->where('tahun', $tahun)
                     ->where_not_in('iku_id', $validIkuIds)
                     ->update('lkpj_bab3_iku_perkembangan', ['deleted_at' => date('Y-m-d H:i:s')]);
        }

        // Query data segar murni dari relasi IKU RPJMD
        $itemsCapaian = $this->db
            ->where('kodewilayah', $KodeWilayah)
            ->where('tahun', $tahun)
            ->where_in('iku_id', $validIkuIds)
            ->where('deleted_at IS NULL')
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get('lkpj_bab3_iku_capaian')
            ->result_array();

        $itemsPerkembangan = $this->db
            ->where('kodewilayah', $KodeWilayah)
            ->where('tahun', $tahun)
            ->where_in('iku_id', $validIkuIds)
            ->where('deleted_at IS NULL')
            ->order_by('urutan', 'ASC')
            ->order_by('id', 'ASC')
            ->get('lkpj_bab3_iku_perkembangan')
            ->result_array();

        // Siapkan lookup map perkembangan untuk mengisi nilai kolom dinamis pada capaian
        $perkMap = [];
        foreach ($itemsPerkembangan as $pRow) {
            if (!empty($pRow['iku_id'])) {
                $perkMap[$pRow['iku_id']] = $pRow;
            }
        }

        $thMin3 = $tahun - 3;
        $thMin2 = $tahun - 2;
        $thMin1 = $tahun - 1;

        foreach ($itemsCapaian as &$cRow) {
            $iId = (int)($cRow['iku_id'] ?? 0);
            $pItem = $perkMap[$iId] ?? null;

            $getVal = function($yr) use ($pItem, $cRow) {
                if ($pItem) {
                    $f = 'nilai_' . $yr;
                    if (isset($pItem[$f]) && $pItem[$f] !== null && $pItem[$f] !== '') {
                        return (float)$pItem[$f];
                    }
                }
                $legacyField = 'realisasi_' . $yr;
                if (isset($cRow[$legacyField]) && $cRow[$legacyField] !== null && $cRow[$legacyField] !== '') {
                    return (float)$cRow[$legacyField];
                }
                return null;
            };

            $cRow['val_th_min3'] = $getVal($thMin3);
            $cRow['val_th_min2'] = $getVal($thMin2);
            $cRow['val_th_min1'] = $getVal($thMin1);

            $targetAktif = null;
            if (isset($cRow['target']) && $cRow['target'] !== null && $cRow['target'] !== '') {
                $targetAktif = (float)$cRow['target'];
            } elseif ($tahun == 2025 && isset($cRow['target_2025']) && $cRow['target_2025'] !== null && $cRow['target_2025'] !== '') {
                $targetAktif = (float)$cRow['target_2025'];
            }
            $cRow['target_th_aktif'] = $targetAktif;

            $realisasiAktif = $getVal($tahun);
            if ($realisasiAktif === null && isset($cRow['realisasi']) && $cRow['realisasi'] !== null && $cRow['realisasi'] !== '') {
                $realisasiAktif = (float)$cRow['realisasi'];
            }
            if ($realisasiAktif === null && $tahun == 2025 && isset($cRow['realisasi_2025']) && $cRow['realisasi_2025'] !== null && $cRow['realisasi_2025'] !== '') {
                $realisasiAktif = (float)$cRow['realisasi_2025'];
            }
            $cRow['realisasi_th_aktif'] = $realisasiAktif;

            $capaianAktif = null;
            if ($targetAktif !== null && $targetAktif > 0 && $realisasiAktif !== null) {
                $capaianAktif = round(($realisasiAktif / $targetAktif) * 100, 2);
            } elseif ($tahun == 2025 && isset($cRow['capaian_2025']) && $cRow['capaian_2025'] !== null && $cRow['capaian_2025'] !== '') {
                $capaianAktif = (float)$cRow['capaian_2025'];
            }
            $cRow['capaian_th_aktif'] = $capaianAktif;
        }
        unset($cRow);

        $misiRowspan = [];
        $tujuanRowspan = [];
        foreach ($itemsCapaian as $row) {
            $mKey = trim($row['misi']);
            $tKey = $mKey . '|||' . trim($row['tujuan']);
            if (!isset($misiRowspan[$mKey])) $misiRowspan[$mKey] = 0;
            if (!isset($tujuanRowspan[$tKey])) $tujuanRowspan[$tKey] = 0;
            $misiRowspan[$mKey]++;
            $tujuanRowspan[$tKey]++;
        }

        return [
            'itemsCapaian' => $itemsCapaian,
            'misiRowspan' => $misiRowspan,
            'tujuanRowspan' => $tujuanRowspan,
            'itemsPerkembangan' => $itemsPerkembangan
        ];
    }


    public function BAB3_4() {
        $bagian = strtoupper($this->input->get('bagian', TRUE) ?: '');
        if ($bagian === 'B') {
            $this->BAB3_4B();
        } else {
            $this->BAB3_4A();
        }
    }

    public function BAB3_4A() {
        $Header['Halaman'] = 'BAB 3.4 Bagian A: Capaian Kinerja IKU';

        $is_logged_in = $this->is_logged_in();
        $is_role_4 = $this->is_role_4();

        // Data yang ditampilkan hanya sesuai wilayah session login
        if ($is_logged_in) {
            $KodeWilayah = $this->session->userdata('KodeWilayah') ?: (isset($_SESSION['KodeWilayah']) ? $_SESSION['KodeWilayah'] : $this->get_kode_wilayah());
        } else {
            $KodeWilayah = $this->get_kode_wilayah();
        }
        if (empty($KodeWilayah)) {
            $KodeWilayah = '35.12';
        }
        $tahun = (int)($this->input->get('tahun', TRUE) ?: (isset($_SESSION['Tahun']) ? $_SESSION['Tahun'] : 2025));

        $can_crud = $this->can_crud_lkpj_for_wilayah($KodeWilayah);

        // Pastikan tabel database tersedia
        $this->ensure_bab3_4a_tables_exist($KodeWilayah, $tahun);

        $namaWilayah = 'Kabupaten Situbondo';
        if (!empty($KodeWilayah)) {
            $wilayah = $this->db->where('Kode', $KodeWilayah)->get('kodewilayah')->row_array();
            if ($wilayah) {
                $namaWilayah = ucwords(strtolower($wilayah['Nama']));
            }
        }

        // Tarik data murni dari relasi master IKU di RPJMD
        $syncData = $this->sync_from_rpjmd_iku($KodeWilayah, $tahun);
        $itemsCapaian = $syncData['itemsCapaian'];
        $misiRowspan = $syncData['misiRowspan'];
        $tujuanRowspan = $syncData['tujuanRowspan'];
        $itemsPerkembangan = $syncData['itemsPerkembangan'];

        // Ambil master misi & tujuan untuk kebutuhan tampilan
        $listMisi = $this->db->where('KodeWilayah', $KodeWilayah)->where('deleted_at IS NULL')->get('misirpjmd')->result_array();
        $listTujuan = $this->db->where('KodeWilayah', $KodeWilayah)->where('deleted_at IS NULL')->get('tujuanrpjmd')->result_array();

        // Data Provinsi & KabKota untuk dropdown filter wilayah
        $provKode = substr($KodeWilayah, 0, 2);
        $listProvinsi = $this->db->where("Kode LIKE '__'")->order_by('Nama', 'ASC')->get('kodewilayah')->result_array();
        $listKabKota = !empty($provKode) ? $this->db->where("Kode LIKE '{$provKode}.__'")->order_by('Nama', 'ASC')->get('kodewilayah')->result_array() : [];

        $Data = [
            'IsLoggedIn' => $is_logged_in,
            'IsRole4' => $is_role_4,
            'NamaInstansi' => isset($_SESSION['NamaInstansi']) ? $_SESSION['NamaInstansi'] : '',
            'CanCrud' => $can_crud,
            'IsDaerah' => $is_logged_in && !$is_role_4,
            'KodeWilayah' => $KodeWilayah,
            'NamaWilayah' => $namaWilayah,
            'Provinsi' => $listProvinsi,
            'KabKota' => $listKabKota,
            'TahunAktif' => $tahun,
            'ListTahun' => [2027, 2026, 2025, 2024, 2023, 2022, 2021],
            'ItemsCapaian' => $itemsCapaian,
            'MisiRowspan' => $misiRowspan,
            'TujuanRowspan' => $tujuanRowspan,
            'ItemsPerkembangan' => $itemsPerkembangan,
            'ListMisi' => $listMisi,
            'ListTujuan' => $listTujuan,
            'ControllerName' => 'Instansi'
        ];

        $this->load->view('Daerah/header', $Header);
        $this->load->view('Daerah/BAB3_4A', $Data);
    }

    public function GetBab3IkuCapaian() {
        header('Content-Type: application/json');

        $id = (int)$this->input->get('id', TRUE);
        $KodeWilayah = $this->input->get('kodewilayah', TRUE) ?: ($this->get_kode_wilayah() ?: '35.12');

        $data = $this->db->where('id', $id)
                         ->where('kodewilayah', $KodeWilayah)
                         ->where('deleted_at IS NULL')
                         ->get('lkpj_bab3_iku_capaian')
                         ->row_array();

        if ($data) {
            echo json_encode(['status' => 'success', 'data' => $data]);
        } else {
            echo json_encode(['status' => 'error', 'message' => 'Data tidak ditemukan']);
        }
    }

    public function SaveBab3IkuCapaian() {
        header('Content-Type: application/json');

        try {
            $id = (int)$this->input->post('id', TRUE);
            $tahun = (int)($this->input->post('tahun', TRUE) ?: 2025);
            $KodeWilayah = $this->input->post('kodewilayah', TRUE) ?: ($this->get_kode_wilayah() ?: '35.12');

            if (!$this->can_crud_lkpj_for_wilayah($KodeWilayah)) {
                echo json_encode(['status' => 'error', 'message' => 'Akses ditolak: Akun Anda hanya memiliki hak akses untuk mengubah data wilayah Anda sendiri.']);
                return;
            }

            $parseDecimal = function($val) {
                if ($val === null || $val === '') return null;
                $clean = str_replace([' ', 'Rp'], '', (string)$val);
                $clean = str_replace(',', '.', $clean);
                return is_numeric($clean) ? (float)$clean : null;
            };

            $misi = trim((string)$this->input->post('misi', TRUE));
            $tujuan = trim((string)$this->input->post('tujuan', TRUE));
            $indikator = trim((string)$this->input->post('indikator_iku', TRUE));
            $satuan = trim((string)$this->input->post('satuan', TRUE) ?: 'Indeks');
            $urutan = (int)($this->input->post('urutan', TRUE) ?: 1);

            $r22 = $parseDecimal($this->input->post('realisasi_2022', TRUE));
            $r23 = $parseDecimal($this->input->post('realisasi_2023', TRUE));
            $r24 = $parseDecimal($this->input->post('realisasi_2024', TRUE));
            $t25 = $parseDecimal($this->input->post('target_2025', TRUE));
            $real25 = $parseDecimal($this->input->post('realisasi_2025', TRUE));
            
            // Hitung capaian otomatis jika tidak diisi manual
            $cap25 = $parseDecimal($this->input->post('capaian_2025', TRUE));
            if ($cap25 === null && $t25 !== null && $real25 !== null && $t25 != 0) {
                $cap25 = round(($real25 / $t25) * 100, 2);
            }

            if (empty($misi) || empty($tujuan) || empty($indikator)) {
                throw new Exception('Misi, Tujuan, dan Indikator IKU wajib diisi.');
            }

            $saveData = [
                'kodewilayah' => $KodeWilayah,
                'tahun' => $tahun,
                'misi' => $misi,
                'tujuan' => $tujuan,
                'indikator_iku' => $indikator,
                'satuan' => $satuan,
                'realisasi_2022' => $r22,
                'realisasi_2023' => $r23,
                'realisasi_2024' => $r24,
                'target_2025' => $t25,
                'realisasi_2025' => $real25,
                'capaian_2025' => $cap25,
                'urutan' => $urutan,
                'updated_at' => date('Y-m-d H:i:s')
            ];

            if ($id > 0) {
                $this->db->where('id', $id)->where('kodewilayah', $KodeWilayah)->update('lkpj_bab3_iku_capaian', $saveData);
                $msg = 'Data Capaian IKU berhasil diperbarui.';
            } else {
                $saveData['created_at'] = date('Y-m-d H:i:s');
                $this->db->insert('lkpj_bab3_iku_capaian', $saveData);
                $msg = 'Data Capaian IKU baru berhasil ditambahkan.';
            }

            echo json_encode(['status' => 'success', 'message' => $msg]);
        } catch (Exception $e) {
            echo json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

