        $listKabKota = !empty($provKode) ? $this->db->where("Kode LIKE '{$provKode}.__'")->order_by('Nama', 'ASC')->get('kodewilayah')->result_array() : [];

        $Data = [
            'IsLoggedIn' => $is_logged_in,
