                break;

            case 'tbl_1.5':
                $this->db->where('deleted_at IS NULL')->where('kodewilayah', $KodeWilayah);
                if ($tahun) $this->db->where('tahun', $tahun);
                $items = $this->db->order_by('nomor', 'ASC')->order_by('id', 'ASC')->get('lkpj_bab1_tabel1_5')->result_array();
